insert into public.dua_categories (slug, name, name_ur, name_te, description, description_ur, description_te, sort_order, is_active)
values
('waking', 'Waking up', 'بیدار ہونے پر', 'నిద్ర లేచినప్పుడు', 'The very first words upon opening one''s eyes.', 'نیند سے آنکھ کھلنے کے پہلے الفاظ۔', 'నిద్ర నుండి లేచినప్పుడు పలికే మొదటి మాటలు.', 0, true),
('morning', 'Morning athkar', 'صبح کے اذکار', 'ఉదయపు అజ్కార్', 'Said after Fajr, roughly from dawn until sunrise.', 'فجر کے بعد، طلوعِ آفتاب تک پڑھے جاتے ہیں۔', 'ఫజ్ర్ తర్వాత, సూర్యోదయం వరకు చదవబడతాయి.', 10, true),
('evening', 'Evening athkar', 'شام کے اذکار', 'సాయంత్ర అజ్కార్', 'Said after ''Asr, roughly from mid-afternoon until sunset.', 'عصر کے بعد، غروبِ آفتاب تک پڑھے جاتے ہیں۔', 'అస్ర్ తర్వాత, సూర్యాస్తమయం వరకు చదవబడతాయి.', 20, true),
('sleep', 'Before sleeping', 'سونے سے پہلے', 'నిద్రపోయే ముందు', 'The wind-down of the day, and protection through the night.', 'دن کے اختتام پر، اور رات بھر حفاظت کے لیے۔', 'రోజు ముగింపులో, మరియు రాత్రంతా రక్షణ కోసం.', 30, true),
('wudu', 'Wudu', 'وضو', 'వుజూ', 'Before and after ablution.', 'وضو سے پہلے اور بعد میں۔', 'వుజూకు ముందు మరియు తర్వాత.', 40, true),
('masjid', 'Adhan & masjid', 'اذان اور مسجد', 'అజాన్ & మసీదు', 'Responding to the call to prayer, and entering or leaving the masjid.', 'اذان کا جواب دینا، اور مسجد میں داخل ہونا یا نکلنا۔', 'అజాన్‌కు సమాధానం ఇవ్వడం, మసీదులో ప్రవేశించడం లేదా బయలుదేరడం.', 50, true),
('salah', 'In the prayer', 'نماز کے دوران', 'నమాజ్‌లో', 'Supplications recited within the salah itself.', 'نماز کے اندر پڑھی جانے والی دعائیں۔', 'నమాజ్ లోపల చదివే దుఆలు.', 60, true),
('witr', 'Witr & Qunut', 'وتر اور قنوت', 'విత్ర్ & ఖునూత్', 'The final night prayer.', 'رات کی آخری نماز۔', 'రాత్రి చివరి నమాజ్.', 70, true),
('home', 'Home & family', 'گھر اور خاندان', 'ఇల్లు & కుటుంబం', 'Entering the house, marriage, and family life.', 'گھر میں داخل ہونا، نکاح، اور خانگی زندگی۔', 'ఇంట్లోకి ప్రవేశించడం, వివాహం, మరియు కుటుంబ జీవితం.', 80, true),
('food', 'Food & drink', 'کھانا اور پینا', 'ఆహారం & పానీయం', 'Before and after eating, and as a guest.', 'کھانے سے پہلے اور بعد میں، اور بطور مہمان۔', 'తినే ముందు మరియు తర్వాత, మరియు అతిథిగా ఉన్నప్పుడు.', 90, true),
('fasting', 'Fasting & Ramadan', 'روزہ اور رمضان', 'ఉపవాసం & రంజాన్', 'Breaking the fast and the last ten nights.', 'روزہ کھولنا، اور آخری عشرہ۔', 'ఉపవాసం విరమించడం, మరియు చివరి పది రోజులు.', 100, true),
('dressing', 'Dressing & appearance', 'لباس اور وضع قطع', 'దుస్తులు & రూపం', 'New clothes, the toilet, and looking in the mirror.', 'نئے کپڑے، بیت الخلا، اور آئینہ دیکھنا۔', 'కొత్త బట్టలు, మరుగుదొడ్డి, మరియు అద్దంలో చూసుకోవడం.', 110, true),
('travel', 'Travel', 'سفر', 'ప్రయాణం', 'Setting out, arriving at a town, and returning home.', 'سفر پر نکلنا، شہر میں داخل ہونا، اور گھر واپسی۔', 'ప్రయాణం మొదలుపెట్టడం, ఊరిలోకి చేరుకోవడం, మరియు ఇంటికి తిరిగి రావడం.', 120, true),
('weather', 'Weather & nature', 'موسم اور فطرت', 'వాతావరణం & ప్రకృతి', 'Rain, wind, thunder, and the new moon.', 'بارش، ہوا، گرج، اور نیا چاند۔', 'వర్షం, గాలి, ఉరుము, మరియు నూతన చంద్రుడు.', 130, true),
('anxiety', 'Anxiety & distress', 'پریشانی اور غم', 'ఆందోళన & వేదన', 'For worry, fear, and moments the heart feels heavy.', 'فکر، خوف، اور دل کے بوجھل لمحات کے لیے۔', 'చింత, భయం, మరియు మనసు బరువుగా అనిపించే క్షణాల కోసం.', 140, true),
('anger', 'Anger & difficulty', 'غصہ اور مشکلات', 'కోపం & కష్టాలు', 'For anger, debt, and difficult circumstances.', 'غصے، قرض، اور مشکل حالات کے لیے۔', 'కోపం, అప్పు, మరియు కష్టమైన పరిస్థితుల కోసం.', 150, true),
('sickness', 'Sickness & healing', 'بیماری اور شفا', 'అనారోగ్యం & స్వస్థత', 'For visiting the sick, and to say over oneself when unwell.', 'مریض کی عیادت کے لیے، اور خود بیمار ہونے پر پڑھنے کے لیے۔', 'రోగిని పరామర్శించడానికి, మరియు స్వయంగా అనారోగ్యంతో ఉన్నప్పుడు చదవడానికి.', 160, true),
('grief', 'Grief, loss & funerals', 'غم، نقصان اور جنازہ', 'దుఃఖం, నష్టం & అంత్యక్రియలు', 'For bereavement, calamity, and the return to Allah.', 'موت، مصیبت، اور اللہ کی طرف لوٹنے کے لیے۔', 'మరణం, ఆపద, మరియు అల్లాహ్ వైపుకు తిరిగి రావడం కోసం.', 170, true),
('knowledge', 'Knowledge & guidance', 'علم اور رہنمائی', 'జ్ఞానం & మార్గదర్శనం', 'For students, decisions, and seeking Allah''s guidance.', 'طالب علموں، فیصلوں، اور اللہ کی رہنمائی حاصل کرنے کے لیے۔', 'విద్యార్థుల కోసం, నిర్ణయాల కోసం, మరియు అల్లాహ్ మార్గదర్శనం కోరడం కోసం.', 180, true),
('repentance', 'Repentance & forgiveness', 'توبہ اور استغفار', 'పశ్చాత్తాపం & క్షమాపణ', 'Turning back to Allah in seeking pardon.', 'اللہ کی طرف معافی مانگتے ہوئے لوٹنا۔', 'క్షమాపణ కోరుతూ అల్లాహ్ వైపుకు మరలడం.', 190, true),
('hajj', 'Hajj & Umrah', 'حج اور عمرہ', 'హజ్ & ఉమ్రా', 'The talbiyah and key stations of pilgrimage.', 'تلبیہ اور حج کے اہم مقامات۔', 'తల్బియా మరియు హజ్ యొక్క ముఖ్యమైన ఘట్టాలు.', 200, true),
('social', 'Social & etiquette', 'معاشرتی آداب', 'సామాజిక మర్యాదలు', 'Greetings, sneezing, gatherings, and congratulations.', 'سلام، چھینک، مجلسیں، اور مبارکباد۔', 'సలాం, తుమ్ము, సమావేశాలు, మరియు అభినందనలు.', 210, true),
('quranic', 'Qur''anic supplications', 'قرآنی دعائیں', 'ఖురాన్ దుఆలు', 'A further selection of the ''Rabbana'' duas taught in the Qur''an.', 'قرآن میں سکھائی گئی ''ربّنا'' دعاؤں کا مزید انتخاب۔', 'ఖురాన్‌లో బోధించిన ''రబ్బనా'' దుఆల మరింత ఎంపిక.', 220, true),
('market', 'Market & provision', 'بازار اور رزق', 'మార్కెట్ & జీవనోపాధి', 'Entering the marketplace, and seeking wholesome, beneficial provision.', 'بازار میں داخل ہونا، اور حلال و اچھی روزی طلب کرنا۔', 'మార్కెట్‌లోకి ప్రవేశించడం, మరియు మంచి, ప్రయోజనకరమైన జీవనోపాధి కోరడం.', 230, true),
('faith', 'Doubts & whispers', 'وسوسے اور شکوک', 'సందేహాలు & దురాలోచనలు', 'For intrusive doubts about faith, or distraction during prayer.', 'ایمان کے بارے میں وسوسوں، یا نماز میں دھیان بھٹکنے کے لیے۔', 'విశ్వాసం గురించి అనుమానాలు, లేదా నమాజ్‌లో దృష్టి మళ్లడం కోసం.', 240, true),
('hamd-o-sana', 'Praise & Glorification', null, null, 'Hamd o Sana — praising Allah before supplicating', null, null, 250, true),
('durood-sharif', 'Durood Sharif', null, null, 'Sending peace and blessings upon the Prophet ﷺ', null, null, 260, true),
('protection-and-safety', 'Protection & Safety', null, null, 'Supplications for protection and safety', null, null, 270, true),
('protection-from-enemy', 'Protection from an Enemy', null, null, 'Supplications when fearing an enemy or oppressor', null, null, 280, true),
('night-protection', 'Protection During the Night', null, null, 'Supplications for the night', null, null, 290, true),
('bad-dream', 'Bad Dreams & Fright in Sleep', null, null, 'What to do and say after a bad dream or fright while sleeping', null, null, 300, true),
('evil-eye', 'Evil Eye', null, null, 'Protection from the evil eye and envy', null, null, 310, true),
('protection-from-magic', 'Protection from Magic', null, null, 'Protection from sorcery and its effects', null, null, 320, true),
('jinn-and-shayateen', 'Protection from Jinn & Shayateen', null, null, 'Seeking refuge from the jinn and devils', null, null, 330, true),
('visiting-the-sick', 'Visiting the Sick', null, null, 'Supplications when visiting a sick person', null, null, 340, true),
('trials-and-adversity', 'Trials & Adversity', null, null, 'On seeing someone in a trial or hardship', null, null, 350, true),
('deceased-maghfirat', 'Forgiveness for the Deceased', null, null, 'Supplications for the forgiveness of the deceased', null, null, 360, true),
('istighfar', 'Seeking Forgiveness (Istighfar)', null, null, 'Supplications for forgiveness of sins', null, null, 370, true),
('relief-from-distress', 'Relief from Sorrow & Distress', null, null, 'Supplications for relief from grief and distress', null, null, 380, true),
('maqbool-duain', 'Accepted Supplications', null, null, 'Maqbool Duain — comprehensive supplications', null, null, 390, true),
('after-salah', 'After the Prayer', null, null, 'Masnoon adhkar after the obligatory prayers', null, null, 400, true)
on conflict (slug) do nothing;

insert into public.duas (slug, title, title_ur, arabic, transliteration_latin, transliteration_telugu, transliteration_urdu, translation_en, translation_ur, description, repeat_count, source_type, source_collection, source_reference, hadith_number, hadith_grade, quran_refs, audio_url, status, verification_status, review_notes, origin, wyn_ids, sort_order)
values
('waking-upon-waking', 'Upon waking', 'نیند سے بیدار ہونے کے بعد پڑھے جانے والے اذکار', 'الْحَمْدُ لِلَّهِ الَّذِي أَحْيَانَا بَعْدَ مَا أَمَاتَنَا وَإِلَيْهِ النُّشُورُ', 'Al-ḥamdu lillāhi-lladhī aḥyānā ba''da mā amātanā wa ilayhi-n-nushūr', 'అల్హమ్దు లిల్లాహిల్లదీ అహ్యానా బఅద మా అమాతనా వ ఇలైహిన్నుషూర్', null, 'All praise is for Allah who gave us life after having caused us to die, and unto Him is the resurrection.', null, null, null, 'hadith', 'Sahih al-Bukhari', 'Bukhari', null, null, '[]'::jsonb, null, 'published', 'unchecked', null, 'iqs', '{}'::text[], 0),
('waking-upon-waking-an-alternate-wording', 'Upon waking, an alternate wording', 'نیند سے بیدار ہونے کے بعد پڑھے جانے والے اذکار', 'الْحَمْدُ لِلَّهِ الَّذِي عَافَانِي فِي جَسَدِي وَرَدَّ عَلَيَّ رُوحِي وَأَذِنَ لِي بِذِكْرِهِ', 'Al-ḥamdu lillāhi-lladhī ''āfānī fī jasadī wa radda ''alayya rūḥī wa adhina lī bi-dhikrih', 'అల్హమ్దు లిల్లాహిల్లదీ ఆఫానీ ఫీ జసదీ వ రద్ద అలైయ రూహీ వ అదిన లీ బిదిక్రిహ్', null, 'Praise is for Allah who restored to me my health, returned my soul to me, and permitted me to remember Him.', null, null, null, 'hadith', 'Jami'' at-Tirmidhi', 'Tirmidhi', null, null, '[]'::jsonb, null, 'published', 'unchecked', null, 'iqs', '{}'::text[], 1),
('morning-morning-remembrance', 'Morning remembrance', 'صبح اور شام کے وقت پڑھے جانے والے اذکار', 'أَصْبَحْنَا وَأَصْبَحَ الْمُلْكُ لِلَّهِ، وَالْحَمْدُ لِلَّهِ، لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ', 'Aṣbaḥnā wa aṣbaḥa-l-mulku lillāh, wal-ḥamdu lillāh, lā ilāha illallāhu waḥdahu lā sharīka lah', 'అస్బహ్నా వ అస్బహల్ముల్కు లిల్లాహ్, వల్హమ్దు లిల్లాహ్, లా ఇలాహ ఇల్లల్లాహు వహ్దహు లా షరీక లహ్', null, 'We have reached the morning, and dominion belongs to Allah. Praise is for Allah; there is no god but Allah alone, without partner.', null, null, 1, 'hadith', 'Sahih Muslim', 'Muslim', '6908', null, '[]'::jsonb, null, 'published', 'unchecked', 'Hadith number Sahih Muslim 6908 from the Wa Iyyaka inventory (WYN-0010), reference verified against the hadith corpus in that research; numbering follows that source.', 'iqs', array['WYN-0010']::text[], 2),
('morning-by-you-we-reach-morning-and-evening', 'By You we reach morning and evening', 'صبح اور شام کے وقت پڑھے جانے والے اذکار', 'اللَّهُمَّ بِكَ أَصْبَحْنَا، وَبِكَ أَمْسَيْنَا، وَبِكَ نَحْيَا، وَبِكَ نَمُوتُ، وَإِلَيْكَ النُّشُورُ', 'Allāhumma bika aṣbaḥnā, wa bika amsaynā, wa bika naḥyā, wa bika namūtu, wa ilayka-n-nushūr', 'అల్లాహుమ్మ బిక అస్బహ్నా, వ బిక అమ్సైనా, వ బిక నహ్యా, వ బిక నమూతు, వ ఇలైకన్నుషూర్', null, 'O Allah, by You we reach the morning, by You we reach the evening, by You we live, by You we die, and unto You is the resurrection.', null, null, null, 'hadith', 'Jami'' at-Tirmidhi', 'Tirmidhi', '3391', 'Sahih (grade as printed in Wa Iyyaka Nasta''in)', '[]'::jsonb, null, 'published', 'unchecked', 'Hadith number Jami'' at-Tirmidhi 3391 from the Wa Iyyaka inventory (WYN-0007), reference verified against the hadith corpus in that research; numbering follows that source.', 'iqs', array['WYN-0007']::text[], 3),
('morning-sayyid-al-istighfar-master-of-seeking-forgiveness', 'Sayyid al-Istighfar (master of seeking forgiveness)', 'صبح اور شام کے وقت پڑھے جانے والے اذکار', 'اللَّهُمَّ أَنْتَ رَبِّي لَا إِلَهَ إِلَّا أَنْتَ، خَلَقْتَنِي وَأَنَا عَبْدُكَ، وَأَنَا عَلَى عَهْدِكَ وَوَعْدِكَ مَا اسْتَطَعْتُ', 'Allāhumma anta rabbī lā ilāha illā ant, khalaqtanī wa ana ''abduk, wa ana ''alā ''ahdika wa wa''dika mastaṭa''t', 'అల్లాహుమ్మ అన్త రబ్బీ లా ఇలాహ ఇల్లా అన్త్, ఖలఖ్తనీ వ అన అబ్దుక్, వ అన అలా అహ్దిక వ వఅదిక మస్తటఅత్', null, 'O Allah, You are my Lord, there is no god but You. You created me and I am Your servant, and I am upon Your covenant and promise as much as I am able.', null, null, null, 'hadith', 'Sahih al-Bukhari', 'Bukhari', '6306', null, '[]'::jsonb, null, 'published', 'unchecked', 'Hadith number Sahih al-Bukhari 6306 from the Wa Iyyaka inventory (WYN-0017), reference verified against the hadith corpus in that research; numbering follows that source.', 'iqs', array['WYN-0017', 'WYN-0134']::text[], 4),
('morning-protection', 'Protection', 'صبح اور شام کے وقت پڑھے جانے والے اذکار', 'بِسْمِ اللَّهِ الَّذِي لَا يَضُرُّ مَعَ اسْمِهِ شَيْءٌ فِي الْأَرْضِ وَلَا فِي السَّمَاءِ وَهُوَ السَّمِيعُ الْعَلِيمُ', 'Bismillāhi-lladhī lā yaḍurru ma''a-smihi shay''un fil-arḍi wa lā fis-samā''i wa huwa-s-samī''u-l-''alīm', 'బిస్మిల్లాహిల్లదీ లా యడుర్రు మఅస్మిహి షైఉన్ ఫిలర్డి వ లా ఫిస్సమాఇ వ హువస్సమీఉల్అలీమ్', null, 'In the name of Allah, with whose name nothing on earth or in the heaven can cause harm, and He is the All-Hearing, the All-Knowing.', null, null, 3, 'hadith', 'Sunan Abi Dawud, Jami'' at-Tirmidhi', 'Abu Dawud, Tirmidhi', '5088', 'Sahih (grade as printed in Wa Iyyaka Nasta''in)', '[]'::jsonb, null, 'published', 'unchecked', 'Hadith number Sunan Abu Dawud 5088 from the Wa Iyyaka inventory (WYN-0013), reference verified against the hadith corpus in that research; numbering follows that source.', 'iqs', array['WYN-0013']::text[], 5),
('morning-contentment-with-allah', 'Contentment with Allah', 'صبح اور شام کے وقت پڑھے جانے والے اذکار', 'رَضِيتُ بِاللَّهِ رَبًّا وَبِالْإِسْلَامِ دِينًا وَبِمُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَبِيًّا', 'Raḍītu billāhi rabbā, wa bil-islāmi dīnā, wa bi-Muḥammadin ṣallallāhu ''alayhi wa sallama nabiyyā', 'రడీతు బిల్లాహి రబ్బా, వ బిలిస్లామి దీనా, వ బిముహమ్మదిన్ సల్లల్లాహు అలైహి వ సల్లమ నబియ్యా', null, 'I am pleased with Allah as my Lord, with Islam as my religion, and with Muhammad ﷺ as my Prophet.', null, null, null, 'hadith', 'Sunan Abi Dawud, Jami'' at-Tirmidhi', 'Abu Dawud, Tirmidhi', null, null, '[]'::jsonb, null, 'published', 'unchecked', null, 'iqs', array['WYN-0011']::text[], 6),
('evening-evening-remembrance', 'Evening remembrance', 'صبح اور شام کے وقت پڑھے جانے والے اذکار', 'أَمْسَيْنَا وَأَمْسَى الْمُلْكُ لِلَّهِ، وَالْحَمْدُ لِلَّهِ، لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ', 'Amsaynā wa amsā-l-mulku lillāh, wal-ḥamdu lillāh, lā ilāha illallāhu waḥdahu lā sharīka lah', 'అమ్సైనా వ అమ్సాల్ముల్కు లిల్లాహ్, వల్హమ్దు లిల్లాహ్, లా ఇలాహ ఇల్లల్లాహు వహ్దహు లా షరీక లహ్', null, 'We have reached the evening, and dominion belongs to Allah. Praise is for Allah; there is no god but Allah alone, without partner.', null, null, 1, 'hadith', 'Sahih Muslim', 'Muslim', null, null, '[]'::jsonb, null, 'published', 'unchecked', null, 'iqs', '{}'::text[], 7),
('evening-seeking-refuge-at-nightfall', 'Seeking refuge at nightfall', 'صبح اور شام کے وقت پڑھے جانے والے اذکار', 'أَعُوذُ بِكَلِمَاتِ اللَّهِ التَّامَّاتِ مِنْ شَرِّ مَا خَلَقَ', 'A''ūdhu bi-kalimāti-llāhi-t-tāmmāti min sharri mā khalaq', 'అఊదు బికలిమాతిల్లాహిత్తామ్మాతి మిన్ షర్రి మా ఖలఖ్', null, 'I seek refuge in the perfect words of Allah from the evil of what He has created.', null, null, null, 'hadith', 'Sahih Muslim', 'Muslim', '6880', null, '[]'::jsonb, null, 'published', 'unchecked', 'Hadith number Sahih Muslim 6880 from the Wa Iyyaka inventory (WYN-0012), reference verified against the hadith corpus in that research; numbering follows that source.', 'iqs', array['WYN-0012']::text[], 8),
('ayat-al-kursi', 'Ayat al-Kursi', null, 'ٱللَّهُ لَآ إِلَـٰهَ إِلَّا هُوَ ٱلْحَىُّ ٱلْقَيُّومُ ۚ لَا تَأْخُذُهُۥ سِنَةٌ وَلَا نَوْمٌ ۚ لَّهُۥ مَا فِى ٱلسَّمَـٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۗ مَن ذَا ٱلَّذِى يَشْفَعُ عِندَهُۥٓ إِلَّا بِإِذْنِهِۦ ۚ يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ ۖ وَلَا يُحِيطُونَ بِشَىْءٍ مِّنْ عِلْمِهِۦٓ إِلَّا بِمَا شَآءَ ۚ وَسِعَ كُرْسِيُّهُ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضَ ۖ وَلَا يَـُٔودُهُۥ حِفْظُهُمَا ۚ وَهُوَ ٱلْعَلِىُّ ٱلْعَظِيمُ', 'Allahu laaa ilaaha illaa Huwal Haiyul Qaiyoom; laa taakhuzuhoo sinatunw wa laa nawm; lahoo maa fissamaawaati wa maa fil ard; man zal lazee yashfa''u indahooo illaa bi-iznih; ya''lamu maa baina aydeehim wa mww khalfahum wa laa yuheetoona bishai''im min ''ilmihee illaa bimaa shaaa''; wasi''a Kursiyyuhus samaawaati wal arda wa laa ya''ooduho hifzuhumaa; wa Huwal Aliyyul ''Azeem', null, null, 'Allah - there is no deity except Him, the Ever-Living, the Sustainer of [all] existence. Neither drowsiness overtakes Him nor sleep. To Him belongs whatever is in the heavens and whatever is on the earth. Who is it that can intercede with Him except by His permission? He knows what is [presently] before them and what will be after them, and they encompass not a thing of His knowledge except for what He wills. His Kursi extends over the heavens and the earth, and their preservation tires Him not. And He is the Most High, the Most Great.', 'اللہ، وہ زندہ جاوید ہستی، جو تمام کائنات کو سنبھالے ہوئے ہے، اُس کے سوا کوئی خدا نہیں ہے وہ نہ سوتا ہے اور نہ اُسے اونگھ لگتی ہے زمین اور آسمانوں میں جو کچھ ہے، اُسی کا ہے کون ہے جو اُس کی جناب میں اُس کی اجازت کے بغیر سفارش کر سکے؟ جو کچھ بندوں کے سامنے ہے اسے بھی وہ جانتا ہے اور جو کچھ اُن سے اوجھل ہے، اس سے بھی وہ واقف ہے اور اُس کی معلومات میں سے کوئی چیز اُن کی گرفت ادراک میں نہیں آسکتی الّا یہ کہ کسی چیز کا علم وہ خود ہی اُن کو دینا چاہے اُس کی حکومت آسمانوں اور زمین پر چھائی ہوئی ہے اور اُن کی نگہبانی اس کے لیے کوئی تھکا دینے والا کام نہیں ہے بس وہی ایک بزرگ و برتر ذات ہے', null, null, 'quran', null, 'Qur''an 2:255', null, null, '[{"surah":2,"ayah_from":255,"ayah_to":255}]'::jsonb, null, 'published', 'needs_review', 'Arabic = Qur''an 2:255 from IqraSpace''s Quran dataset (text_uthmani); English = Saheeh International; Latin transliteration = Al Quran Cloud en.transliteration. Telugu transliteration removed (the legacy text covered only the first words) — app falls back to Latin until a complete Telugu transliteration is supplied. NEEDS MANUAL VERIFICATION of transliteration only. Wa Iyyaka entry WYN-0006 appears to be longer than this text (Ayat al-Kursi. IQS evening#2 stops at "la ta''khudhuhu sinatun wa la nawm" (verified truncation); sleep#2 duplicates it. Qur''an 2:255 reference matches.). Wa Iyyaka entry WYN-0055 appears to be longer than this text (Instruction entry: recite Ayat al-Kursi at night. IQS sleep#2 covers the same practice (Bukhari) but its Arabic is truncated.). translation_ur = Urdu translation of the Qur''an (Al Quran Cloud ur.maududi, Tafheem ul Quran), unmodified.', 'iqs', array['WYN-0006', 'WYN-0055', 'WYN-0174']::text[], 9),
('three-quls', 'The three Quls (Ikhlas, Falaq, Nas)', null, 'قُلْ هُوَ ٱللَّهُ أَحَدٌ ٱللَّهُ ٱلصَّمَدُ لَمْ يَلِدْ وَلَمْ يُولَدْ وَلَمْ يَكُن لَّهُۥ كُفُوًا أَحَدٌۢ
قُلْ أَعُوذُ بِرَبِّ ٱلْفَلَقِ مِن شَرِّ مَا خَلَقَ وَمِن شَرِّ غَاسِقٍ إِذَا وَقَبَ وَمِن شَرِّ ٱلنَّفَّـٰثَـٰتِ فِى ٱلْعُقَدِ وَمِن شَرِّ حَاسِدٍ إِذَا حَسَدَ
قُلْ أَعُوذُ بِرَبِّ ٱلنَّاسِ مَلِكِ ٱلنَّاسِ إِلَـٰهِ ٱلنَّاسِ مِن شَرِّ ٱلْوَسْوَاسِ ٱلْخَنَّاسِ ٱلَّذِى يُوَسْوِسُ فِى صُدُورِ ٱلنَّاسِ مِنَ ٱلْجِنَّةِ وَٱلنَّاسِ', 'Qul huwal laahu ahad Allah hus-samad Lam yalid wa lam yoolad Wa lam yakul-lahu kufuwan ahad
Qul a''uzoo bi rabbil-falaq Min sharri ma khalaq Wa min sharri ghasiqin iza waqab Wa min sharrin-naffaa-thaati fil ''uqad Wa min shar ri haasidin iza hasad
Qul a''uzu birabbin naas Malikin naas Ilaahin naas Min sharril was waasil khannaas Al lazee yuwas wisu fee sudoorin naas Minal jinnati wan naas', null, null, 'Al-Ikhlas: Say, "He is Allah, [who is] One, Allah, the Eternal Refuge. He neither begets nor is born, Nor is there to Him any equivalent."
Al-Falaq: Say, "I seek refuge in the Lord of daybreak From the evil of that which He created And from the evil of darkness when it settles And from the evil of the blowers in knots And from the evil of an envier when he envies."
An-Nas: Say, "I seek refuge in the Lord of mankind, The Sovereign of mankind. The God of mankind, From the evil of the retreating whisperer - Who whispers [evil] into the breasts of mankind - From among the jinn and mankind."', 'الإخلاص: کہو، وہ اللہ ہے، یکتا اللہ سب سے بے نیاز ہے اور سب اس کے محتاج ہیں نہ اس کی کوئی اولاد ہے اور نہ وہ کسی کی اولاد اور کوئی اس کا ہمسر نہیں ہے
الفلق: کہو، میں پناہ مانگتا ہوں صبح کے رب کی ہر اُس چیز کے شر سے جو اُس نے پیدا کی ہے اور رات کی تاریکی کے شر سے جب کہ وہ چھا جائے اور گرہوں میں پھونکنے والوں (یا والیوں) کے شر سے اور حاسد کے شر سے جب کہ وہ حسد کرے
الناس: کہو، میں پناہ مانگتا ہوں انسانوں کے رب انسانوں کے بادشاہ انسانوں کے حقیقی معبود کی اُس وسوسہ ڈالنے والے کے شر سے جو بار بار پلٹ کر آتا ہے جو لوگوں کے دلوں میں وسوسے ڈالتا ہے خواہ وہ جنوں میں سے ہو یا انسانوں میں سے', null, 3, 'quran', null, 'Qur''an 112, 113, 114', null, null, '[{"surah":112,"ayah_from":1,"ayah_to":4},{"surah":113,"ayah_from":1,"ayah_to":5},{"surah":114,"ayah_from":1,"ayah_to":6}]'::jsonb, null, 'published', 'needs_review', 'Arabic = Surahs 112-114 from IqraSpace''s Quran dataset (text_uthmani, Bismillah not prefixed); English = Saheeh International; Latin = Al Quran Cloud en.transliteration. Telugu transliteration removed (legacy covered only 1 ayah) — app falls back to Latin. NEEDS MANUAL VERIFICATION of transliteration only. Wa Iyyaka entry WYN-0019 appears to be longer than this text (Surah al-Ikhlas. IQS evening#3 holds only Al-Ikhlas v1 (verified data error); one IQS entry stands for three WYN entries.). Wa Iyyaka entry WYN-0020 appears to be longer than this text (Surah al-Falaq: IQS evening#3 does not contain its Arabic text (verified data error).). Wa Iyyaka entry WYN-0021 appears to be longer than this text (Surah an-Nas: IQS evening#3 does not contain its Arabic text (verified data error).). translation_ur = Urdu translation of the Qur''an (Al Quran Cloud ur.maududi, Tafheem ul Quran), unmodified.', 'iqs', array['WYN-0019', 'WYN-0020', 'WYN-0021', 'WYN-0175']::text[], 10),
('sleep-before-sleeping', 'Before sleeping', 'سوتے وقت پڑھے جانے والے اذکار', 'بِاسْمِكَ اللَّهُمَّ أَمُوتُ وَأَحْيَا', 'Bismika-llāhumma amūtu wa aḥyā', 'బిస్మికల్లాహుమ్మ అమూతు వ అహ్యా', null, 'In Your name, O Allah, I die and I live.', null, null, null, 'hadith', 'Sahih al-Bukhari', 'Bukhari', null, null, '[]'::jsonb, null, 'published', 'unchecked', null, 'iqs', '{}'::text[], 11),
('sleep-seeking-protection-through-the-night', 'Seeking protection through the night', 'سوتے وقت پڑھے جانے والے اذکار', 'اللَّهُمَّ قِنِي عَذَابَكَ يَوْمَ تَبْعَثُ عِبَادَكَ', 'Allāhumma qinī ''adhābaka yawma tab''athu ''ibādak', 'అల్లాహుమ్మ ఖినీ అదాబక యౌమ తబ్అతు ఇబాదక్', null, 'O Allah, protect me from Your punishment on the day You resurrect Your servants.', null, null, null, 'hadith', 'Sunan Abi Dawud, Jami'' at-Tirmidhi', 'Abu Dawud, Tirmidhi', null, null, '[]'::jsonb, null, 'published', 'unchecked', null, 'iqs', '{}'::text[], 12),
('bismillah', 'Bismillah', null, 'بِسْمِ اللَّهِ', 'Bismillāh', 'బిస్మిల్లాహ్', null, 'In the name of Allah.', null, null, null, 'hadith', 'Sunan Abi Dawud, Jami'' at-Tirmidhi, Sunan Ibn Majah', 'Abu Dawud, Tirmidhi, Ibn Majah', null, null, '[]'::jsonb, null, 'published', 'unchecked', null, 'iqs', '{}'::text[], 13),
('wudu-after-completing-wudu', 'After completing wudu', 'وضوء سے فارغ ہونے کے بعد پڑھی جانے والی دعائیں', 'أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ، اللَّهُمَّ اجْعَلْنِي مِنَ التَّوَّابِينَ وَاجْعَلْنِي مِنَ الْمُتَطَهِّرِينَ', 'Ash-hadu an lā ilāha illallāhu waḥdahu lā sharīka lah, wa ash-hadu anna Muḥammadan ''abduhu wa rasūluh. Allāhumma-j''alnī minat-tawwābīna wa-j''alnī minal-mutaṭahhirīn', 'అష్హదు అన్ లా ఇలాహ ఇల్లల్లాహు వహ్దహు లా షరీక లహ్, వ అష్హదు అన్న ముహమ్మదన్ అబ్దుహు వ రసూలుహ్. అల్లాహుమ్మజ్అల్నీ మినత్తౌవాబీన వజ్అల్నీ మినల్ముతటహ్హిరీన్', null, 'I bear witness that there is no god but Allah alone, without partner, and that Muhammad is His servant and messenger. O Allah, make me among those who repent often and among those who purify themselves.', null, null, null, 'hadith', 'Sahih Muslim, Jami'' at-Tirmidhi', 'Muslim, Tirmidhi', null, null, '[]'::jsonb, null, 'published', 'unchecked', null, 'iqs', '{}'::text[], 14),
('masjid-after-the-adhan', 'After the adhan', 'اذان کے دوران اور بعد پڑھی جانے والی دعاء', 'اللَّهُمَّ رَبَّ هَذِهِ الدَّعْوَةِ التَّامَّةِ وَالصَّلَاةِ الْقَائِمَةِ، آتِ مُحَمَّدًا الْوَسِيلَةَ وَالْفَضِيلَةَ، وَابْعَثْهُ مَقَامًا مَحْمُودًا الَّذِي وَعَدْتَهُ', 'Allāhumma Rabba hādhihi-d-da''wati-t-tāmmati wa-ṣ-ṣalāti-l-qā''imah, āti Muḥammadani-l-wasīlata wal-faḍīlah, wab''athhu maqāman maḥmūdani-lladhī wa''adtah', 'అల్లాహుమ్మ రబ్బ హాదిహిద్దఅవతిత్తామ్మతి వస్సలాతిల్ఖాఇమహ్, ఆతి ముహమ్మదనిల్వసీలత వల్ఫడీలహ్, వబ్అత్హు మఖామన్ మహ్మూదనిల్లదీ వఅద్తహ్', null, 'O Allah, Lord of this perfect call and established prayer, grant Muhammad the intercession and favor, and raise him to the praised station You promised him.', null, null, null, 'hadith', 'Sahih al-Bukhari', 'Bukhari', null, null, '[]'::jsonb, null, 'published', 'unchecked', null, 'iqs', '{}'::text[], 15),
('masjid-entering-the-masjid', 'Entering the masjid', 'مسجد میں داخل ہوتے وقت پڑھنے کی دعاء', 'اللَّهُمَّ افْتَحْ لِي أَبْوَابَ رَحْمَتِكَ', 'Allāhumma-ftaḥ lī abwāba raḥmatik', 'అల్లాహుమ్మఫ్తహ్ లీ అబ్వాబ రహ్మతిక్', null, 'O Allah, open the doors of Your mercy for me.', null, null, null, 'hadith', 'Sahih Muslim', 'Muslim', null, null, '[]'::jsonb, null, 'published', 'unchecked', null, 'iqs', '{}'::text[], 16),
('masjid-leaving-the-masjid', 'Leaving the masjid', 'مسجد سے نکلتے وقت پڑھنے کی دعاء', 'اللَّهُمَّ إِنِّي أَسْأَلُكَ مِنْ فَضْلِكَ', 'Allāhumma innī as''aluka min faḍlik', 'అల్లాహుమ్మ ఇన్నీ అస్అలుక మిన్ ఫడ్లిక్', null, 'O Allah, I ask You from Your bounty.', null, null, null, 'hadith', 'Sahih Muslim', 'Muslim', null, null, '[]'::jsonb, null, 'published', 'unchecked', null, 'iqs', '{}'::text[], 17),
('salah-opening-dua-istiftah', 'Opening dua (istiftah)', 'تکبیر تحریمہ کے بعد پڑھی جانے والی دعائیں', 'اللَّهُمَّ بَاعِدْ بَيْنِي وَبَيْنَ خَطَايَايَ كَمَا بَاعَدْتَ بَيْنَ الْمَشْرِقِ وَالْمَغْرِبِ، اللَّهُمَّ نَقِّنِي مِنْ خَطَايَايَ كَمَا يُنَقَّى الثَّوْبُ الْأَبْيَضُ مِنَ الدَّنَسِ', 'Allāhumma bā''id baynī wa bayna khaṭāyāya kamā bā''adta baynal-mashriqi wal-maghrib. Allāhumma naqqinī min khaṭāyāya kamā yunaqqath-thawbul-abyaḍu minad-danas', 'అల్లాహుమ్మ బాఇద్ బైనీ వ బైన ఖటాయాయ కమా బాఅద్త బైనల్మష్రిఖి వల్మఘ్రిబ్. అల్లాహుమ్మ నఖ్ఖినీ మిన్ ఖటాయాయ కమా యునఖ్ఖత్తౌబులబ్యడు మినద్దనస్', null, 'O Allah, distance me from my sins as You have distanced the East from the West. O Allah, cleanse me of my sins as a white garment is cleansed of dirt.', null, null, null, 'hadith', 'Sahih al-Bukhari, Sahih Muslim', 'Bukhari, Muslim', null, null, '[]'::jsonb, null, 'published', 'unchecked', null, 'iqs', '{}'::text[], 18),
('salah-in-ruku-bowing', 'In ruku (bowing)', 'رکوع میں پڑھی جانے والی دعائیں', 'سُبْحَانَ رَبِّيَ الْعَظِيمِ', 'Subḥāna Rabbiya-l-''Aẓīm', 'సుబ్హాన రబ్బియల్అజీమ్', null, 'Glory be to my Lord, the Magnificent.', null, null, null, 'hadith', 'Sahih Muslim, Sunan Abi Dawud', 'Muslim, Abu Dawud', null, null, '[]'::jsonb, null, 'published', 'unchecked', null, 'iqs', '{}'::text[], 19),
('salah-in-sujud-prostration', 'In sujud (prostration)', 'سجدہ میں پڑھی جانے والی دعاء', 'سُبْحَانَ رَبِّيَ الْأَعْلَى', 'Subḥāna Rabbiya-l-A''lā', 'సుబ్హాన రబ్బియలఅలా', null, 'Glory be to my Lord, the Most High.', null, null, null, 'hadith', 'Sahih Muslim, Sunan Abi Dawud', 'Muslim, Abu Dawud', null, null, '[]'::jsonb, null, 'published', 'unchecked', null, 'iqs', '{}'::text[], 20),
('salah-between-the-two-prostrations', 'Between the two prostrations', 'جلسہ یعنی دو سجدوں کے درمیان پڑھی جانے والی دعاء', 'اللَّهُمَّ اغْفِرْ لِي، وَارْحَمْنِي، وَاجْبُرْنِي، وَارْفَعْنِي، وَارْزُقْنِي، وَاهْدِنِي، وَعَافِنِي', 'Allāhumma-ghfir lī, wa-rḥamnī, wa-jburnī, wa-rfa''nī, wa-rzuqnī, wa-hdinī, wa ''āfinī', 'అల్లాహుమ్మఘ్ఫిర్ లీ, వర్హమ్నీ, వజ్బుర్నీ, వర్ఫఅనీ, వర్జుఖ్నీ, వహ్దినీ, వ ఆఫినీ', null, 'O Allah, forgive me, have mercy on me, make up my shortfall, raise my rank, provide for me, guide me, and grant me well-being.', null, null, null, 'hadith', 'Sunan Abi Dawud, Jami'' at-Tirmidhi, Sunan Ibn Majah', 'Abu Dawud, Tirmidhi, Ibn Majah', null, null, '[]'::jsonb, null, 'published', 'unchecked', null, 'iqs', '{}'::text[], 21),
('salah-the-tashahhud', 'The tashahhud', 'تشہد میں پڑھی جانے والی التحیات', 'التَّحِيَّاتُ لِلَّهِ وَالصَّلَوَاتُ وَالطَّيِّبَاتُ، السَّلَامُ عَلَيْكَ أَيُّهَا النَّبِيُّ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ، السَّلَامُ عَلَيْنَا وَعَلَى عِبَادِ اللَّهِ الصَّالِحِينَ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ', 'At-taḥiyyātu lillāhi waṣ-ṣalawātu waṭ-ṭayyibāt, as-salāmu ''alayka ayyuhan-Nabiyyu wa raḥmatullāhi wa barakātuh, as-salāmu ''alaynā wa ''alā ''ibādillāhi-ṣ-ṣāliḥīn, ash-hadu an lā ilāha illallāh, wa ash-hadu anna Muḥammadan ''abduhu wa rasūluh', 'అత్తహియ్యాతు లిల్లాహి వస్సలౌఆతు వట్టైయిబాత్, అస్సలాము అలైక ఐయుహన్నబియ్యు వ రహ్మతుల్లాహి వ బరకాతుహ్, అస్సలాము అలైనా వ అలా ఇబాదిల్లాహిస్సాలిహీన్, అష్హదు అన్ లా ఇలాహ ఇల్లల్లాహ్, వ అష్హదు అన్న ముహమ్మదన్ అబ్దుహు వ రసూలుహ్', null, 'All greetings, prayers, and good deeds are for Allah. Peace be upon you, O Prophet, and the mercy and blessings of Allah. Peace be upon us and upon the righteous servants of Allah. I bear witness there is no god but Allah, and that Muhammad is His servant and messenger.', null, null, null, 'hadith', 'Sahih al-Bukhari, Sahih Muslim', 'Bukhari, Muslim', null, null, '[]'::jsonb, null, 'published', 'unchecked', null, 'iqs', '{}'::text[], 22),
('salah-before-the-final-salam', 'Before the final salam', 'آخری تشہد اور سلام پھیرنے سے پہلے پڑھی جانے والی دعائیں', 'اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ عَذَابِ جَهَنَّمَ، وَمِنْ عَذَابِ الْقَبْرِ، وَمِنْ فِتْنَةِ الْمَحْيَا وَالْمَمَاتِ، وَمِنْ شَرِّ فِتْنَةِ الْمَسِيحِ الدَّجَّالِ', 'Allāhumma innī a''ūdhu bika min ''adhābi jahannam, wa min ''adhābi-l-qabr, wa min fitnati-l-maḥyā wal-mamāt, wa min sharri fitnati-l-masīḥi-d-dajjāl', 'అల్లాహుమ్మ ఇన్నీ అఊదు బిక మిన్ అదాబి జహన్నమ్, వ మిన్ అదాబిల్ఖబ్ర్, వ మిన్ ఫిత్నతిల్మహ్యా వల్మమాత్, వ మిన్ షర్రి ఫిత్నతిల్మసీహిద్దజ్జాల్', null, 'O Allah, I seek refuge in You from the punishment of Hell, from the punishment of the grave, from the trials of life and death, and from the evil of the trial of the False Messiah.', null, null, null, 'hadith', 'Sahih Muslim', 'Muslim', null, null, '[]'::jsonb, null, 'published', 'unchecked', null, 'iqs', array['WYN-0047']::text[], 23),
('salah-rising-from-ruku-hisnul-muslim-ch-18', 'Rising from ruku (Hisnul Muslim ch.18)', 'رکوع سے سر اٹھاتے وقت یعنی قومہ میں پڑھی جانے والی دعاء', 'سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ، رَبَّنَا وَلَكَ الْحَمْدُ', 'Sami''a-llāhu liman ḥamidah, Rabbanā wa laka-l-ḥamd', 'సమిఅల్లాహు లిమన్ హమిదహ్, రబ్బనా వ లకల్హమ్ద్', null, 'Allah hears whoever praises Him. Our Lord, and to You is all praise.', null, null, null, 'hadith', 'Sahih al-Bukhari, Sahih Muslim', 'Bukhari, Muslim', null, null, '[]'::jsonb, null, 'published', 'unchecked', null, 'iqs', '{}'::text[], 24),
('salah-salutations-on-the-prophet-after-tashahhud-salat-ibrahimiyyah-ch', 'Salutations on the Prophet after tashahhud (Salat Ibrahimiyyah, ch.23)', 'تشھد کے بعد نبی ﷺ پر پڑھا جانے والا درود ابراہیم', 'اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ كَمَا صَلَّيْتَ عَلَى إِبْرَاهِيمَ وَعَلَى آلِ إِبْرَاهِيمَ إِنَّكَ حَمِيدٌ مَجِيدٌ، اللَّهُمَّ بَارِكْ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ كَمَا بَارَكْتَ عَلَى إِبْرَاهِيمَ وَعَلَى آلِ إِبْرَاهِيمَ إِنَّكَ حَمِيدٌ مَجِيدٌ', 'Allāhumma ṣalli ''alā Muḥammadin wa ''alā āli Muḥammad, kamā ṣallayta ''alā Ibrāhīma wa ''alā āli Ibrāhīm, innaka ḥamīdum-majīd. Allāhumma bārik ''alā Muḥammadin wa ''alā āli Muḥammad, kamā bārakta ''alā Ibrāhīma wa ''alā āli Ibrāhīm, innaka ḥamīdum-majīd', 'అల్లాహుమ్మ సల్లి అలా ముహమ్మదిన్ వ అలా ఆలి ముహమ్మద్, కమా సల్లైత అలా ఇబ్రాహీమ వ అలా ఆలి ఇబ్రాహీమ్, ఇన్నక హమీదుమ్మజీద్. అల్లాహుమ్మ బారిక్ అలా ముహమ్మదిన్ వ అలా ఆలి ముహమ్మద్, కమా బారక్త అలా ఇబ్రాహీమ వ అలా ఆలి ఇబ్రాహీమ్, ఇన్నక హమీదుమ్మజీద్', null, 'O Allah, send blessings upon Muhammad and the family of Muhammad, as You sent blessings upon Ibrahim and the family of Ibrahim; indeed You are Praiseworthy, Glorious. O Allah, bless Muhammad and the family of Muhammad, as You blessed Ibrahim and the family of Ibrahim; indeed You are Praiseworthy, Glorious.', null, null, null, 'hadith', 'Sahih al-Bukhari', 'Bukhari', null, null, '[]'::jsonb, null, 'published', 'unchecked', null, 'iqs', array['WYN-0004']::text[], 25),
('salah-prostration-of-quran-recitation-sajdat-at-tilawah', 'Prostration of Qur''an recitation, sajdat at-tilawah', 'سجدہ تلاوت کی دعاء', 'سَجَدَ وَجْهِيَ لِلَّذِي خَلَقَهُ وَشَقَّ سَمْعَهُ وَبَصَرَهُ بِحَوْلِهِ وَقُوَّتِهِ', 'Sajada wajhiya lilladhī khalaqahu wa shaqqa sam''ahu wa baṣarahu bi-ḥawlihi wa quwwatih', 'సజద వజ్హియ లిల్లదీ ఖలఖహు వ షఖ్ఖ సమ్అహు వ బసరహు బిహౌలిహి వ ఖువ్వతిహ్', null, 'My face has prostrated to the One who created it and fashioned its hearing and sight by His might and power.', null, null, null, 'hadith', 'Jami'' at-Tirmidhi', 'Tirmidhi', null, null, '[]'::jsonb, null, 'published', 'unchecked', 'Hisnul Muslim chapter 21 (from legacy title).', 'iqs', '{}'::text[], 26),
('salah-general-remembrance-after-the-salam', 'General remembrance after the salam', 'سلام پھیرنے کے بعد پڑھے جانے والے اذکار', 'أَسْتَغْفِرُ اللَّهَ (×٣)، اللَّهُمَّ أَنْتَ السَّلَامُ وَمِنْكَ السَّلَامُ تَبَارَكْتَ يَا ذَا الْجَلَالِ وَالْإِكْرَامِ', 'Astaghfirullāh (x3), Allāhumma anta-s-salāmu wa minka-s-salām, tabārakta yā dha-l-jalāli wal-ikrām', 'అస్తఘ్ఫిరుల్లాహ్ (x3), అల్లాహుమ్మ అన్తస్సలాము వ మిన్కస్సలామ్, తబారక్త యా దల్జలాలి వలిక్రామ్', null, 'I seek Allah''s forgiveness (three times). O Allah, You are Peace and from You comes peace; blessed are You, O Owner of majesty and honor.', null, null, null, 'hadith', 'Sahih Muslim', 'Muslim', null, null, '[]'::jsonb, null, 'published', 'needs_review', 'Hisnul Muslim chapter 25 (from legacy title). Repetition counts are embedded in the translation text (forgiveness phrase ''three times'' inside a multi-part dhikr); structure manually.', 'iqs', array['WYN-0136', 'WYN-0164', 'WYN-0165']::text[], 27),
('witr-qunut-in-witr', 'Qunut in Witr', 'قنوت وتر کی دعائیں', 'اللَّهُمَّ اهْدِنِي فِيمَنْ هَدَيْتَ، وَعَافِنِي فِيمَنْ عَافَيْتَ، وَتَوَلَّنِي فِيمَنْ تَوَلَّيْتَ، وَبَارِكْ لِي فِيمَا أَعْطَيْتَ، وَقِنِي شَرَّ مَا قَضَيْتَ، فَإِنَّكَ تَقْضِي وَلَا يُقْضَى عَلَيْكَ، إِنَّهُ لَا يَذِلُّ مَنْ وَالَيْتَ، تَبَارَكْتَ رَبَّنَا وَتَعَالَيْتَ', 'Allāhumma-hdinī fīman hadayt, wa ''āfinī fīman ''āfayt, wa tawallanī fīman tawallayt, wa bārik lī fīmā a''ṭayt, wa qinī sharra mā qaḍayt, fa innaka taqḍī wa lā yuqḍā ''alayk, innahu lā yadhillu man wālayt, tabārakta Rabbanā wa ta''ālayt', 'అల్లాహుమ్మహ్దినీ ఫీమన్ హదైత్, వ ఆఫినీ ఫీమన్ ఆఫైత్, వ తౌఅల్లనీ ఫీమన్ తౌఅల్లైత్, వ బారిక్ లీ ఫీమా అఅటైత్, వ ఖినీ షర్ర మా ఖడైత్, ఫ ఇన్నక తఖ్డీ వ లా యుఖ్డా అలైక్, ఇన్నహు లా యదిల్లు మన్ వాలైత్, తబారక్త రబ్బనా వ తఆలైత్', null, 'O Allah, guide me among those You have guided, grant me well-being among those You have granted well-being, take care of me among those You have taken care of, bless what You have given me, and protect me from the evil You have decreed. You decree and none decrees over You; whoever You support is never humiliated. Blessed and Exalted are You, our Lord.', null, null, null, 'hadith', 'Sunan Abi Dawud, Jami'' at-Tirmidhi, Sunan an-Nasa''i', 'Abu Dawud, Tirmidhi, Nasa''i', null, null, '[]'::jsonb, null, 'published', 'unchecked', null, 'iqs', '{}'::text[], 28),
('witr-after-finishing-witr', 'After finishing Witr', 'نماز وتر کے بعد کی دعاء', 'سُبْحَانَ الْمَلِكِ الْقُدُّوسِ', 'Subḥāna-l-Maliki-l-Quddūs', 'సుబ్హానల్మలికిల్ఖుద్దూస్', null, 'Glory be to the King, the Most Holy (said three times, prolonging the voice on the third).', null, null, 3, 'hadith', 'Sunan an-Nasa''i, Sunan ad-Daraqutni', 'Nasa''i, Daraqutni', null, null, '[]'::jsonb, null, 'published', 'unchecked', null, 'iqs', '{}'::text[], 29),
('home-entering-the-home', 'Entering the home', 'گھر میں داخل ہوتے وقت پڑھنے کی دعاء', 'بِسْمِ اللَّهِ وَلَجْنَا، وَبِسْمِ اللَّهِ خَرَجْنَا، وَعَلَى رَبِّنَا تَوَكَّلْنَا', 'Bismillāhi walajnā, wa bismillāhi kharajnā, wa ''alā rabbinā tawakkalnā', 'బిస్మిల్లాహి వలజ్నా, వ బిస్మిల్లాహి ఖరజ్నా, వ అలా రబ్బినా తౌఅక్కల్నా', null, 'In the name of Allah we enter, in the name of Allah we leave, and upon our Lord we depend.', null, null, null, 'hadith', 'Sunan Abi Dawud', 'Abu Dawud', null, null, '[]'::jsonb, null, 'published', 'unchecked', null, 'iqs', '{}'::text[], 30),
('home-leaving-the-home', 'Leaving the home', 'گھر سے نکلتے وقت پڑھنے کی دعاء', 'بِسْمِ اللَّهِ، تَوَكَّلْتُ عَلَى اللَّهِ، وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ', 'Bismillāh, tawakkaltu ''alallāh, wa lā ḥawla wa lā quwwata illā billāh', 'బిస్మిల్లాహ్, తౌఅక్కల్తు అలల్లాహ్, వ లా హౌల వ లా ఖువ్వత ఇల్లా బిల్లాహ్', null, 'In the name of Allah, I place my trust in Allah, and there is no might nor power except with Allah.', null, null, null, 'hadith', 'Sunan Abi Dawud, Jami'' at-Tirmidhi', 'Abu Dawud, Tirmidhi', null, null, '[]'::jsonb, null, 'published', 'unchecked', null, 'iqs', array['WYN-0087']::text[], 31),
('home-on-the-wedding-night-for-the-husband', 'On the wedding night, for the husband', 'شادی کرنے والے کی اپنے بیوی کو دعاء اور سواری خریدنے پر دعاء', 'اللَّهُمَّ إِنِّي أَسْأَلُكَ خَيْرَهَا وَخَيْرَ مَا جَبَلْتَهَا عَلَيْهِ، وَأَعُوذُ بِكَ مِنْ شَرِّهَا وَشَرِّ مَا جَبَلْتَهَا عَلَيْهِ', 'Allāhumma innī as''aluka khayrahā wa khayra mā jabaltahā ''alayh, wa a''ūdhu bika min sharrihā wa sharri mā jabaltahā ''alayh', 'అల్లాహుమ్మ ఇన్నీ అస్అలుక ఖైరహా వ ఖైర మా జబల్తహా అలైహ్, వ అఊదు బిక మిన్ షర్రిహా వ షర్రి మా జబల్తహా అలైహ్', null, 'O Allah, I ask You for the good in her and the good You have instilled in her nature, and I seek refuge in You from any harm in her and any harm You have instilled in her nature.', null, null, null, 'hadith', 'Sunan Abi Dawud, Sunan Ibn Majah', 'Abu Dawud, Ibn Majah', null, null, '[]'::jsonb, null, 'published', 'unchecked', null, 'iqs', '{}'::text[], 32),
('home-before-marital-relations', 'Before marital relations', 'بیوی سے ہمبستری سے پہلے پڑھنے کی دعاء', 'بِسْمِ اللَّهِ، اللَّهُمَّ جَنِّبْنَا الشَّيْطَانَ، وَجَنِّبِ الشَّيْطَانَ مَا رَزَقْتَنَا', 'Bismillāh, Allāhumma jannibna-sh-shayṭān, wa jannibi-sh-shayṭāna mā razaqtanā', 'బిస్మిల్లాహ్, అల్లాహుమ్మ జన్నిబ్నష్షైటాన్, వ జన్నిబిష్షైటాన మా రజఖ్తనా', null, 'In the name of Allah. O Allah, keep the devil away from us, and keep the devil away from what You bless us with.', null, null, null, 'hadith', 'Sahih al-Bukhari, Sahih Muslim', 'Bukhari, Muslim', null, null, '[]'::jsonb, null, 'published', 'unchecked', null, 'iqs', array['WYN-0088']::text[], 33),
('home-congratulating-new-parents', 'Congratulating new parents', 'نومولود کی مبارکباد اور مبارکباد سننے والا کیا جواب دے', 'بَارَكَ اللَّهُ لَكَ فِي الْمَوْهُوبِ لَكَ، وَشَكَرْتَ الْوَاهِبَ', 'Bārakallāhu laka fil-mawhūbi lak, wa shakarta-l-wāhib', 'బారకల్లాహు లక ఫిల్మౌహూబి లక్, వ షకర్తల్వాహిబ్', null, 'May Allah bless the child given to you, and may you give thanks to the Giver.', null, null, null, 'other', null, 'General Sunnah practice', null, null, '[]'::jsonb, null, 'published', 'needs_review', 'Reference "General Sunnah practice" is descriptive, with no collection or hadith number — find the source.', 'iqs', '{}'::text[], 34),
('food-if-forgotten-at-the-start', 'If forgotten at the start', 'کھانا کھانے سے پہلے پڑھنے کی دعاء', 'بِسْمِ اللَّهِ أَوَّلَهُ وَآخِرَهُ', 'Bismillāhi awwalahu wa ākhirah', 'బిస్మిల్లాహి ఔవలహు వ ఆఖిరహ్', null, 'In the name of Allah at its beginning and its end.', null, null, null, 'hadith', 'Sunan Abi Dawud, Jami'' at-Tirmidhi', 'Abu Dawud, Tirmidhi', null, null, '[]'::jsonb, null, 'published', 'unchecked', null, 'iqs', '{}'::text[], 35),
('food-after-eating', 'After eating', 'کھانا کھالینے کے بعد کی دعائیں', 'الْحَمْدُ لِلَّهِ الَّذِي أَطْعَمَنِي هَذَا وَرَزَقَنِيهِ مِنْ غَيْرِ حَوْلٍ مِنِّي وَلَا قُوَّةٍ', 'Al-ḥamdu lillāhi-lladhī aṭ''amanī hādhā wa razaqanīhi min ghayri ḥawlim-minnī wa lā quwwah', 'అల్హమ్దు లిల్లాహిల్లదీ అట్అమనీ హాదా వ రజఖనీహి మిన్ ఘైరి హౌలిమ్మిన్నీ వ లా ఖువ్వహ్', null, 'Praise be to Allah who has fed me this and provided it for me, though I was powerless and had no strength of my own.', null, null, null, 'hadith', 'Sunan Abi Dawud, Jami'' at-Tirmidhi, Sunan Ibn Majah', 'Abu Dawud, Tirmidhi, Ibn Majah', null, null, '[]'::jsonb, null, 'published', 'unchecked', null, 'iqs', '{}'::text[], 36),
('food-guests-dua-for-the-host', 'Guest''s dua for the host', 'مہمان کی جانب سے میزبان کے حق میں دعاء', 'اللَّهُمَّ بَارِكْ لَهُمْ فِيمَا رَزَقْتَهُمْ، وَاغْفِرْ لَهُمْ وَارْحَمْهُمْ', 'Allāhumma bārik lahum fīmā razaqtahum, wa-ghfir lahum wa-rḥamhum', 'అల్లాహుమ్మ బారిక్ లహుమ్ ఫీమా రజఖ్తహుమ్, వఘ్ఫిర్ లహుమ్ వర్హమ్హుమ్', null, 'O Allah, bless what You have provided for them, forgive them, and have mercy on them.', null, null, null, 'hadith', 'Sahih Muslim', 'Muslim', null, null, '[]'::jsonb, null, 'published', 'unchecked', null, 'iqs', '{}'::text[], 37),
('food-drinking-milk', 'Drinking milk', null, 'اللَّهُمَّ بَارِكْ لَنَا فِيهِ وَزِدْنَا مِنْهُ', 'Allāhumma bārik lanā fīhi wa zidnā minh', 'అల్లాహుమ్మ బారిక్ లనా ఫీహి వ జిద్నా మిన్హ్', null, 'O Allah, bless it for us and increase it for us.', null, null, null, 'hadith', 'Jami'' at-Tirmidhi', 'Tirmidhi', null, null, '[]'::jsonb, null, 'published', 'unchecked', null, 'iqs', '{}'::text[], 38),
('food-for-someone-who-feeds-or-gives-you-drink', 'For someone who feeds or gives you drink', 'پلانے والے یا پلانے کا ارادہ رکھنے والے کے حق میں دی جانے والی دعاء', 'اللَّهُمَّ أَطْعِمْ مَنْ أَطْعَمَنِي، وَاسْقِ مَنْ سَقَانِي', 'Allāhumma aṭ''im man aṭ''amanī, wa-sqi man saqānī', 'అల్లాహుమ్మ అట్ఇమ్ మన్ అట్అమనీ, వస్ఖి మన్ సఖానీ', null, 'O Allah, feed whoever has fed me, and give drink to whoever has given me drink.', null, null, null, 'hadith', 'Sahih Muslim', 'Muslim', null, null, '[]'::jsonb, null, 'published', 'unchecked', 'Hisnul Muslim chapter 72 (from legacy title).', 'iqs', '{}'::text[], 39),
('fasting-upon-breaking-the-fast', 'Upon breaking the fast', 'روزہ افطار کرتے وقت پڑھنے کی دعائیں', 'ذَهَبَ الظَّمَأُ، وَابْتَلَّتِ الْعُرُوقُ، وَثَبَتَ الْأَجْرُ إِنْ شَاءَ اللَّهُ', 'Dhahabaẓ-ẓama''u wabtallati-l-''urūqu wa thabata-l-ajru in shā''a-llāh', 'దహబజ్జమఉ వబ్తల్లతిల్ఉరూఖు వ తబతలజ్రు ఇన్ షాఅల్లాహ్', null, 'The thirst has gone, the veins are moistened, and the reward is confirmed, if Allah wills.', null, null, null, 'hadith', 'Sunan Abi Dawud', 'Abu Dawud', null, null, '[]'::jsonb, null, 'published', 'unchecked', null, 'iqs', '{}'::text[], 40),
('fasting-as-a-fasting-guest-for-the-host', 'As a fasting guest, for the host', 'افطار کرانے والے لوگوں کے حق میں دی جانے والی دعاء', 'أَفْطَرَ عِنْدَكُمُ الصَّائِمُونَ، وَأَكَلَ طَعَامَكُمُ الْأَبْرَارُ، وَصَلَّتْ عَلَيْكُمُ الْمَلَائِكَةُ', 'Afṭara ''indakumu-ṣ-ṣā''imūn, wa akala ṭa''āmakumu-l-abrār, wa ṣallat ''alaykumu-l-malā''ikah', 'అఫ్టర ఇన్దకుముస్సాఇమూన్, వ అకల టఆమకుములబ్రార్, వ సల్లత్ అలైకుముల్మలాఇకహ్', null, 'May the fasting break their fast at your home, may the righteous eat your food, and may the angels send blessings upon you.', null, null, null, 'hadith', 'Sunan Abi Dawud, Sunan Ibn Majah', 'Abu Dawud, Ibn Majah', null, null, '[]'::jsonb, null, 'published', 'unchecked', null, 'iqs', '{}'::text[], 41),
('fasting-seeking-laylat-al-qadr', 'Seeking Laylat al-Qadr', null, 'اللَّهُمَّ إِنَّكَ عَفُوٌّ تُحِبُّ الْعَفْوَ فَاعْفُ عَنِّي', 'Allāhumma innaka ''afuwwun tuḥibbu-l-''afwa fa''fu ''annī', 'అల్లాహుమ్మ ఇన్నక అఫువ్వున్ తుహిబ్బుల్అఫ్వ ఫఅఫు అన్నీ', null, 'O Allah, You are Most Forgiving and love forgiveness, so forgive me.', null, null, null, 'hadith', 'Jami'' at-Tirmidhi', 'Tirmidhi', null, null, '[]'::jsonb, null, 'published', 'unchecked', null, 'iqs', '{}'::text[], 42),
('dressing-wearing-new-clothes', 'Wearing new clothes', 'نیا کپڑا پہننے والا یہ دعاء پڑھے', 'اللَّهُمَّ لَكَ الْحَمْدُ أَنْتَ كَسَوْتَنِيهِ، أَسْأَلُكَ مِنْ خَيْرِهِ وَخَيْرِ مَا صُنِعَ لَهُ، وَأَعُوذُ بِكَ مِنْ شَرِّهِ وَشَرِّ مَا صُنِعَ لَهُ', 'Allāhumma laka-l-ḥamdu anta kasawtanīh, as''aluka min khayrihi wa khayri mā ṣuni''a lah, wa a''ūdhu bika min sharrihi wa sharri mā ṣuni''a lah', 'అల్లాహుమ్మ లకల్హమ్దు అన్త కసౌతనీహ్, అస్అలుక మిన్ ఖైరిహి వ ఖైరి మా సునిఅ లహ్, వ అఊదు బిక మిన్ షర్రిహి వ షర్రి మా సునిఅ లహ్', null, 'O Allah, all praise is for You; You have clothed me with this. I ask You for its good and the good it was made for, and seek refuge in You from its harm and the harm it was made for.', null, null, null, 'hadith', 'Sunan Abi Dawud, Jami'' at-Tirmidhi', 'Abu Dawud, Tirmidhi', null, null, '[]'::jsonb, null, 'published', 'unchecked', null, 'iqs', '{}'::text[], 43),
('dressing-entering-the-toilet', 'Entering the toilet', 'بیت الخلاء میں داخل ہوتے وقت کی دعاء', 'اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْخُبُثِ وَالْخَبَائِثِ', 'Allāhumma innī a''ūdhu bika mina-l-khubthi wal-khabā''ith', 'అల్లాహుమ్మ ఇన్నీ అఊదు బిక మినల్ఖుబ్తి వల్ఖబాఇత్', null, 'O Allah, I seek refuge in You from male and female devils.', null, null, null, 'hadith', 'Sahih al-Bukhari, Sahih Muslim', 'Bukhari, Muslim', null, null, '[]'::jsonb, null, 'published', 'unchecked', null, 'iqs', array['WYN-0086']::text[], 44),
('dressing-leaving-the-toilet', 'Leaving the toilet', 'بیت الخلاء سے نکلتے وقت پڑھنے کی دعاء', 'غُفْرَانَكَ', 'Ghufrānak', 'ఘుఫ్రానక్', null, 'I seek Your forgiveness.', null, null, null, 'hadith', 'Sunan Abi Dawud, Jami'' at-Tirmidhi, Sunan Ibn Majah', 'Abu Dawud, Tirmidhi, Ibn Majah', null, null, '[]'::jsonb, null, 'published', 'unchecked', null, 'iqs', '{}'::text[], 45),
('dressing-looking-in-the-mirror', 'Looking in the mirror', null, 'اللَّهُمَّ كَمَا حَسَّنْتَ خَلْقِي فَحَسِّنْ خُلُقِي', 'Allāhumma kamā ḥassanta khalqī fa-ḥassin khuluqī', 'అల్లాహుమ్మ కమా హస్సన్త ఖల్ఖీ ఫహస్సిన్ ఖులుఖీ', null, 'O Allah, just as You have made my outward form good, make my character good as well.', null, null, null, 'hadith', 'Musnad Ahmad, Sahih Ibn Hibban', 'Ahmad, Ibn Hibban', null, null, '[]'::jsonb, null, 'published', 'unchecked', null, 'iqs', '{}'::text[], 46),
('travel-when-mounting-a-vehicle-for-travel', 'When mounting a vehicle for travel', 'سواری پر بیٹھنے کی دعاء', 'سُبْحَانَ الَّذِي سَخَّرَ لَنَا هَذَا وَمَا كُنَّا لَهُ مُقْرِنِينَ وَإِنَّا إِلَى رَبِّنَا لَمُنْقَلِبُونَ', 'Subḥāna-lladhī sakhkhara lanā hādhā wa mā kunnā lahu muqrinīn, wa innā ilā rabbinā lamunqalibūn', 'సుబ్హానల్లదీ సఖ్ఖర లనా హాదా వ మా కున్నా లహు ముఖ్రినీన్, వ ఇన్నా ఇలా రబ్బినా లమున్ఖలిబూన్', null, 'Glory be to Him who has subjected this to us, for we could never have accomplished this by ourselves. And indeed, to our Lord we will return.', null, null, null, 'hadith', 'Sahih Muslim', 'Muslim', null, null, '[]'::jsonb, null, 'published', 'unchecked', null, 'iqs', '{}'::text[], 47),
('travel-entering-a-town-or-village', 'Entering a town or village', 'کسی شہر یا بستی میں داخل ہوتے وقت پڑھنے کی دعاء', 'اللَّهُمَّ إِنِّي أَسْأَلُكَ خَيْرَهَا وَخَيْرَ أَهْلِهَا وَخَيْرَ مَا فِيهَا، وَأَعُوذُ بِكَ مِنْ شَرِّهَا وَشَرِّ أَهْلِهَا وَشَرِّ مَا فِيهَا', 'Allāhumma innī as''aluka khayrahā wa khayra ahlihā wa khayra mā fīhā, wa a''ūdhu bika min sharrihā wa sharri ahlihā wa sharri mā fīhā', 'అల్లాహుమ్మ ఇన్నీ అస్అలుక ఖైరహా వ ఖైర అహ్లిహా వ ఖైర మా ఫీహా, వ అఊదు బిక మిన్ షర్రిహా వ షర్రి అహ్లిహా వ షర్రి మా ఫీహా', null, 'O Allah, I ask You for its good, the good of its people, and the good within it, and I seek refuge in You from its harm, the harm of its people, and the harm within it.', null, null, null, 'hadith', 'Sunan an-Nasa''i, al-Mustadrak (al-Hakim)', 'Nasa''i, al-Hakim', null, null, '[]'::jsonb, null, 'published', 'unchecked', null, 'iqs', '{}'::text[], 48),
('travel-returning-from-a-journey', 'Returning from a journey', 'سفر سے واپسی کی دعاء', 'آيِبُونَ تَائِبُونَ عَابِدُونَ لِرَبِّنَا حَامِدُونَ', 'Āyibūna tā''ibūna ''ābidūna li-Rabbinā ḥāmidūn', 'ఆయిబూన తాఇబూన ఆబిదూన లిరబ్బినా హామిదూన్', null, 'We return, repentant, worshipping, and praising our Lord.', null, null, null, 'hadith', 'Sahih al-Bukhari, Sahih Muslim', 'Bukhari, Muslim', null, null, '[]'::jsonb, null, 'published', 'unchecked', null, 'iqs', '{}'::text[], 49),
('travel-the-fuller-traveling-dua', 'The fuller traveling dua', 'آغاز سفر کی دعاء', 'اللَّهُمَّ إِنَّا نَسْأَلُكَ فِي سَفَرِنَا هَذَا الْبِرَّ وَالتَّقْوَى، وَمِنَ الْعَمَلِ مَا تَرْضَى', 'Allāhumma innā nas''aluka fī safarinā hādha-l-birra wat-taqwā, wa mina-l-''amali mā tarḍā', 'అల్లాహుమ్మ ఇన్నా నస్అలుక ఫీ సఫరినా హాదల్బిర్ర వత్తఖ్వా, వ మినల్అమలి మా తర్డా', null, 'O Allah, we ask You for righteousness and piety in this journey of ours, and for deeds that please You.', null, null, null, 'hadith', 'Sahih Muslim', 'Muslim', null, null, '[]'::jsonb, null, 'published', 'unchecked', 'Hisnul Muslim chapter 96 (from legacy title).', 'iqs', '{}'::text[], 50),
('travel-the-travelers-farewell-to-the-one-staying-behind', 'The traveler''s farewell to the one staying behind', 'مسافر کی مقیم کے لئے دعاء', 'أَسْتَوْدِعُ اللَّهَ دِينَكَ، وَأَمَانَتَكَ، وَخَوَاتِيمَ عَمَلِكَ', 'Astawdi''u-llāha dīnaka, wa amānataka, wa khawātīma ''amalik', 'అస్తౌదిఉల్లాహ దీనక, వ అమానతక, వ ఖౌఆతీమ అమలిక్', null, 'I entrust your faith, your integrity, and the outcome of your deeds to Allah.', null, null, null, 'hadith', 'Jami'' at-Tirmidhi', 'Tirmidhi', null, null, '[]'::jsonb, null, 'published', 'unchecked', 'Hisnul Muslim chapter 100 (from legacy title).', 'iqs', '{}'::text[], 51),
('travel-the-one-staying-behind-to-the-traveler', 'The one staying behind, to the traveler', 'مقیم کی مسافر کے لئے دعاء', 'زَوَّدَكَ اللَّهُ التَّقْوَى، وَغَفَرَ ذَنْبَكَ، وَيَسَّرَ لَكَ الْخَيْرَ حَيْثُ كُنْتَ', 'Zawwadaka-llāhu-t-taqwā, wa ghafara dhanbak, wa yassara laka-l-khayra ḥaythu kunt', 'జౌవదకల్లాహుత్తఖ్వా, వ ఘఫర దన్బక్, వ యస్సర లకల్ఖైర హైతు కున్త్', null, 'May Allah equip you with piety, forgive your sins, and make goodness easy for you wherever you are.', null, null, null, 'hadith', 'Jami'' at-Tirmidhi', 'Tirmidhi', null, null, '[]'::jsonb, null, 'published', 'unchecked', 'Hisnul Muslim chapter 101 (from legacy title).', 'iqs', '{}'::text[], 52),
('weather-seeing-rain-clouds-gather', 'Seeing rain clouds gather', 'بارش دیکھ کر کیا کہا جائے', 'اللَّهُمَّ صَيِّبًا نَافِعًا', 'Allāhumma ṣayyiban nāfi''ā', 'అల్లాహుమ్మ సైయిబన్ నాఫిఆ', null, 'O Allah, let it be a beneficial rain.', null, null, null, 'hadith', 'Sahih al-Bukhari', 'Bukhari', null, null, '[]'::jsonb, null, 'published', 'unchecked', null, 'iqs', '{}'::text[], 53),
('weather-after-rainfall', 'After rainfall', 'بارش کے بعد کی دعاء', 'مُطِرْنَا بِفَضْلِ اللَّهِ وَرَحْمَتِهِ', 'Muṭirnā bi-faḍlillāhi wa raḥmatih', 'ముటిర్నా బిఫడ్లిల్లాహి వ రహ్మతిహ్', null, 'We have been given rain by the grace and mercy of Allah.', null, null, null, 'hadith', 'Sahih al-Bukhari, Sahih Muslim', 'Bukhari, Muslim', null, null, '[]'::jsonb, null, 'published', 'unchecked', null, 'iqs', '{}'::text[], 54),
('weather-hearing-thunder', 'Hearing thunder', 'بادل گرجتے وقت پڑھنے کی دعاء', 'سُبْحَانَ الَّذِي يُسَبِّحُ الرَّعْدُ بِحَمْدِهِ وَالْمَلَائِكَةُ مِنْ خِيفَتِهِ', 'Subḥāna-lladhī yusabbiḥu-r-ra''du bi-ḥamdihi wal-malā''ikatu min khīfatih', 'సుబ్హానల్లదీ యుసబ్బిహుర్రఅదు బిహమ్దిహి వల్మలాఇకతు మిన్ ఖీఫతిహ్', null, 'Glory to Him whom the thunder glorifies with praise, and the angels too, out of awe of Him.', null, null, null, 'hadith', 'Muwatta Malik', 'Muwatta Malik', null, null, '[]'::jsonb, null, 'published', 'unchecked', null, 'iqs', '{}'::text[], 55),
('weather-when-the-wind-blows-strongly', 'When the wind blows strongly', 'آندھی کے وقت پڑھنے کی دعائیں', 'اللَّهُمَّ إِنِّي أَسْأَلُكَ خَيْرَهَا وَخَيْرَ مَا فِيهَا وَخَيْرَ مَا أُرْسِلَتْ بِهِ، وَأَعُوذُ بِكَ مِنْ شَرِّهَا وَشَرِّ مَا فِيهَا وَشَرِّ مَا أُرْسِلَتْ بِهِ', 'Allāhumma innī as''aluka khayrahā wa khayra mā fīhā wa khayra mā ursilat bih, wa a''ūdhu bika min sharrihā wa sharri mā fīhā wa sharri mā ursilat bih', 'అల్లాహుమ్మ ఇన్నీ అస్అలుక ఖైరహా వ ఖైర మా ఫీహా వ ఖైర మా ఉర్సిలత్ బిహ్, వ అఊదు బిక మిన్ షర్రిహా వ షర్రి మా ఫీహా వ షర్రి మా ఉర్సిలత్ బిహ్', null, 'O Allah, I ask You for its good, the good within it, and the good it was sent with, and I seek refuge in You from its harm, the harm within it, and the harm it was sent with.', null, null, null, 'hadith', 'Sahih Muslim', 'Muslim', null, null, '[]'::jsonb, null, 'published', 'unchecked', null, 'iqs', '{}'::text[], 56),
('weather-seeing-the-new-crescent-moon', 'Seeing the new crescent moon', 'چاند دیکھنے پر دعاء', 'اللَّهُ أَكْبَرُ، اللَّهُمَّ أَهِلَّهُ عَلَيْنَا بِالْأَمْنِ وَالْإِيمَانِ', 'Allāhu akbar, Allāhumma ahillahu ''alaynā bil-amni wal-īmān', 'అల్లాహు అక్బర్, అల్లాహుమ్మ అహిల్లహు అలైనా బిలమ్ని వలీమాన్', null, 'Allah is the Greatest. O Allah, bring this crescent upon us with security and faith.', null, null, null, 'hadith', 'Jami'' at-Tirmidhi, Sunan ad-Darimi', 'Tirmidhi, Darimi', null, null, '[]'::jsonb, null, 'published', 'unchecked', null, 'iqs', '{}'::text[], 57),
('weather-if-rain-becomes-excessive-or-harmful', 'If rain becomes excessive or harmful', 'بارش ضرورت سے زائد ہوجائے تو کیا دعاء پڑھی جائے', 'اللَّهُمَّ حَوَالَيْنَا وَلَا عَلَيْنَا، اللَّهُمَّ عَلَى الْآكَامِ وَالظِّرَابِ وَبُطُونِ الْأَوْدِيَةِ وَمَنَابِتِ الشَّجَرِ', 'Allāhumma ḥawālaynā wa lā ''alaynā, Allāhumma ''alā-l-ākāmi waẓ-ẓirābi wa buṭūni-l-awdiyati wa manābiti-sh-shajar', 'అల్లాహుమ్మ హౌఆలైనా వ లా అలైనా, అల్లాహుమ్మ అలాలాకామి వజ్జిరాబి వ బుటూనిలౌదియతి వ మనాబితిష్షజర్', null, 'O Allah, around us and not upon us. O Allah, upon the hills, the small mountains, the beds of valleys, and where trees grow.', null, null, null, 'hadith', 'Sahih al-Bukhari', 'Bukhari', null, null, '[]'::jsonb, null, 'published', 'unchecked', 'Hisnul Muslim chapter 66 (from legacy title).', 'iqs', '{}'::text[], 58),
('anxiety-for-anxiety-and-sorrow', 'For anxiety and sorrow', 'فکر مندی اور غم سے نجات کے لئے پڑھی جانے والی دعاء', 'اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْهَمِّ وَالْحَزَنِ، وَالْعَجْزِ وَالْكَسَلِ، وَالْبُخْلِ وَالْجُبْنِ', 'Allāhumma innī a''ūdhu bika minal-hammi wal-ḥazan, wal-''ajzi wal-kasal, wal-bukhli wal-jubn', 'అల్లాహుమ్మ ఇన్నీ అఊదు బిక మినల్హమ్మి వల్హజన్, వల్అజ్జి వల్కసల్, వల్బుఖ్లి వల్జుబ్న్', null, 'O Allah, I seek refuge in You from anxiety and grief, from helplessness and laziness, from miserliness and cowardice.', null, null, null, 'hadith', 'Sahih al-Bukhari', 'Bukhari', null, null, '[]'::jsonb, null, 'published', 'needs_review', 'Wa Iyyaka entry WYN-0152 appears to be longer than this text (Same hadith (Bukhari). The WYN opening continues "...wa dala''id daini wa ghalabatir rijal"; IQS ends at "wal-bukhli wal-jubn". IQS Arabic appears shorter than the printed WYN text. Confirm.).', 'iqs', array['WYN-0152']::text[], 59),
('anxiety-dua-of-yunus-in-the-belly-of-the-whale', 'Dua of Yunus, in the belly of the whale', 'مصیبت کے موقع پر پڑھی جانے والی دعاء', 'لَا إِلَٰهَ إِلَّا أَنْتَ سُبْحَانَكَ إِنِّي كُنْتُ مِنَ الظَّالِمِينَ', 'Lā ilāha illā anta subḥānaka innī kuntu minaẓ-ẓālimīn', 'లా ఇలాహ ఇల్లా అన్త సుబ్హానక ఇన్నీ కున్తు మినజ్జాలిమీన్', null, 'There is no god but You, glory be to You; indeed I was among the wrongdoers.', null, null, null, 'quran', null, 'Qur''an 21:87', '3505', 'Sahih (grade as printed in Wa Iyyaka Nasta''in)', '[{"surah":21,"ayah_from":87,"ayah_to":87}]'::jsonb, null, 'published', 'verified', 'Urdu title match confidence: probable. Arabic matched to the Qur''an dataset (alef-insensitive normalised comparison). Hadith number Jami'' at-Tirmidhi 3505 from the Wa Iyyaka inventory (WYN-0150), reference verified against the hadith corpus in that research; numbering follows that source.', 'iqs', array['WYN-0150', 'WYN-0158']::text[], 60),
('anxiety-when-overwhelmed-by-a-matter', 'When overwhelmed by a matter', 'کوئی کام مشکل ہوجائے تو کیا دعاء پڑھے', 'حَسْبِيَ اللَّهُ لَا إِلَهَ إِلَّا هُوَ عَلَيْهِ تَوَكَّلْتُ وَهُوَ رَبُّ الْعَرْشِ الْعَظِيمِ', 'Ḥasbiyallāhu lā ilāha illā huwa ''alayhi tawakkaltu wa huwa rabbu-l-''arshi-l-''aẓīm', 'హస్బియల్లాహు లా ఇలాహ ఇల్లా హువ అలైహి తౌఅక్కల్తు వ హువ రబ్బుల్అర్షిల్అజీమ్', null, 'Allah is sufficient for me; there is no god but Him. I place my trust in Him, and He is Lord of the Mighty Throne.', null, null, null, 'hadith', 'Sunan Abi Dawud', 'Abu Dawud', null, null, '[]'::jsonb, null, 'published', 'unchecked', null, 'iqs', '{}'::text[], 61),
('anxiety-for-relief-from-hardship', 'For relief from hardship', 'کوئی کام مشکل ہوجائے تو کیا دعاء پڑھے', 'اللَّهُمَّ لَا سَهْلَ إِلَّا مَا جَعَلْتَهُ سَهْلًا، وَأَنْتَ تَجْعَلُ الْحَزْنَ إِذَا شِئْتَ سَهْلًا', 'Allāhumma lā sahla illā mā ja''altahu sahlā, wa anta taj''alu-l-ḥazna idhā shi''ta sahlā', 'అల్లాహుమ్మ లా సహ్ల ఇల్లా మా జఅల్తహు సహ్లా, వ అన్త తజ్అలుల్హజ్న ఇదా షిఅత సహ్లా', null, 'O Allah, nothing is easy except what You make easy, and You make hardship easy whenever You will.', null, null, null, 'hadith', 'Musnad Ahmad', 'Ahmad', null, null, '[]'::jsonb, null, 'published', 'unchecked', 'Urdu title match confidence: probable.', 'iqs', array['WYN-0151']::text[], 62),
('seeking-refuge-from-the-accursed-devil', 'Seeking refuge from the accursed devil', null, 'أَعُوذُ بِاللَّهِ مِنَ الشَّيْطَانِ الرَّجِيمِ', 'A''ūdhu billāhi mina-sh-shayṭāni-r-rajīm', 'అఊదు బిల్లాహి మినష్షైటానిర్రజీమ్', null, 'I seek refuge in Allah from the accursed devil.', null, null, null, 'hadith', 'Sahih al-Bukhari, Sahih Muslim', 'Bukhari, Muslim', '5738', null, '[]'::jsonb, null, 'published', 'needs_review', 'Repetition counts are embedded in the translation text (''spitting lightly to the left three times'' is an instruction, not a recitation count); structure manually. Hadith number Sahih Muslim 5738 from the Wa Iyyaka inventory (WYN-0063), reference verified against the hadith corpus in that research; numbering follows that source.', 'iqs', array['WYN-0063', 'WYN-0085']::text[], 63),
('anger-for-relief-from-debt', 'For relief from debt', 'قرض سے نجات کی دعائیں', 'اللَّهُمَّ اكْفِنِي بِحَلَالِكَ عَنْ حَرَامِكَ، وَأَغْنِنِي بِفَضْلِكَ عَمَّنْ سِوَاكَ', 'Allāhumma-kfinī bi-ḥalālika ''an ḥarāmik, wa aghninī bi-faḍlika ''amman siwāk', 'అల్లాహుమ్మక్ఫినీ బిహలాలిక అన్ హరామిక్, వ అఘ్నినీ బిఫడ్లిక అమ్మన్ సివాక్', null, 'O Allah, suffice me with what You have made lawful instead of what You have made unlawful, and make me independent of all others besides You by Your favor.', null, null, null, 'hadith', 'Jami'' at-Tirmidhi', 'Tirmidhi', null, null, '[]'::jsonb, null, 'published', 'unchecked', null, 'iqs', '{}'::text[], 64),
('sickness-for-healing', 'For healing', 'بیمار پرسی کے وقت بیمار کے حق میں دی جانے والی دعائیں', 'اللَّهُمَّ رَبَّ النَّاسِ أَذْهِبِ الْبَاْسَ اشْفِ أَنْتَ الشَّافِي لَا شِفَاءَ إِلَّا شِفَاؤُكَ شِفَاءً لَا يُغَادِرُ سَقَمًا', 'Allāhumma rabba-n-nāsi adhhibi-l-ba''s, ishfi anta-sh-shāfī, lā shifā''a illā shifā''uk, shifā''an lā yughādiru saqamā', 'అల్లాహుమ్మ రబ్బన్నాసి అద్హిబిల్బఅస్, ఇష్ఫి అన్తష్షాఫీ, లా షిఫాఅ ఇల్లా షిఫాఉక్, షిఫాఅన్ లా యుఘాదిరు సఖమా', null, 'O Allah, Lord of mankind, remove the affliction and heal — You are the Healer, there is no healing except Your healing, a healing that leaves no illness behind.', null, null, null, 'hadith', 'Sahih al-Bukhari, Sahih Muslim', 'Bukhari, Muslim', '5707', null, '[]'::jsonb, null, 'published', 'unchecked', 'Hadith number Sahih Muslim 5707 from the Wa Iyyaka inventory (WYN-0096), reference verified against the hadith corpus in that research; numbering follows that source.', 'iqs', array['WYN-0096', 'WYN-0104']::text[], 65),
('sickness-placing-the-hand-on-the-site-of-pain', 'Placing the hand on the site of pain', 'بیمار پرسی کے وقت بیمار کے حق میں دی جانے والی دعائیں', 'بِسْمِ اللَّهِ (×٣) أَعُوذُ بِاللَّهِ وَقُدْرَتِهِ مِنْ شَرِّ مَا أَجِدُ وَأُحَاذِرُ (×٧)', 'Bismillāh (x3), a''ūdhu billāhi wa qudratihi min sharri mā ajidu wa uḥādhir (x7)', 'బిస్మిల్లాహ్ (x3), అఊదు బిల్లాహి వ ఖుద్రతిహి మిన్ షర్రి మా అజిదు వ ఉహాదిర్ (x7)', null, 'In the name of Allah (three times). I seek refuge in Allah and His power from the evil of what I feel and am wary of (seven times).', null, null, null, 'hadith', 'Sahih Muslim', 'Muslim', '5737', null, '[]'::jsonb, null, 'published', 'needs_review', 'Repetition counts are embedded in the translation text (two parts: ''three times'' and ''seven times''); structure manually. Hadith number Sahih Muslim 5737 from the Wa Iyyaka inventory (WYN-0094), reference verified against the hadith corpus in that research; numbering follows that source.', 'iqs', array['WYN-0094']::text[], 66),
('sickness-visiting-the-sick', 'Visiting the sick', 'بیمار پرسی کے وقت بیمار کے حق میں دی جانے والی دعائیں', 'لَا بَأْسَ طَهُورٌ إِنْ شَاءَ اللَّهُ', 'Lā ba''sa, ṭahūrun in shā''a-llāh', 'లా బఅస, టహూరున్ ఇన్ షాఅల్లాహ్', null, 'No harm — it is a purification, if Allah wills.', null, null, null, 'hadith', 'Sunan Abi Dawud, Jami'' at-Tirmidhi', 'Abu Dawud, Tirmidhi', null, null, '[]'::jsonb, null, 'published', 'unchecked', null, 'iqs', array['WYN-0102']::text[], 67),
('sickness-seeking-refuge-for-a-child-or-loved-one', 'Seeking refuge for a child or loved one', 'بچوں کو اللہ تعالی کی پناہ میں دینے کی دعاء', 'أُعِيذُكُمَا بِكَلِمَاتِ اللَّهِ التَّامَّةِ مِنْ كُلِّ شَيْطَانٍ وَهَامَّةٍ، وَمِنْ كُلِّ عَيْنٍ لَامَّةٍ', 'U''īdhukumā bi-kalimāti-llāhi-t-tāmmati min kulli shayṭānin wa hāmmah, wa min kulli ''aynin lāmmah', 'ఉఈదుకుమా బికలిమాతిల్లాహిత్తామ్మతి మిన్ కుల్లి షైటానిన్ వ హామ్మహ్, వ మిన్ కుల్లి ఐనిన్ లామ్మహ్', null, 'I seek refuge for you both in the perfect words of Allah, from every devil and every poisonous creature, and from every harmful, envious eye.', null, null, null, 'hadith', 'Sahih al-Bukhari', 'Bukhari', null, null, '[]'::jsonb, null, 'published', 'unchecked', null, 'iqs', array['WYN-0071']::text[], 68),
('sickness-talqin-instructing-the-dying', 'Talqin — instructing the dying', 'قریب الموت کو تلقین کرنے کا حکم', 'لَا إِلَهَ إِلَّا اللَّهُ', 'Lā ilāha illallāh', 'లా ఇలాహ ఇల్లల్లాహ్', null, 'There is no god but Allah — gently prompted, not forced, to one who is dying.', null, null, null, 'hadith', 'Sahih Muslim', 'Muslim', null, null, '[]'::jsonb, null, 'published', 'unchecked', null, 'iqs', '{}'::text[], 69),
('grief-upon-hearing-of-a-calamity', 'Upon hearing of a calamity', 'مصیبت کے وقت نعم البدل مانگنے کی دعاء', 'إِنَّا لِلَّهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ', 'Innā lillāhi wa innā ilayhi rāji''ūn', 'ఇన్నా లిల్లాహి వ ఇన్నా ఇలైహి రాజిఊన్', null, 'Indeed we belong to Allah, and indeed to Him we shall return.', null, null, null, 'quran', null, 'Qur''an 2:156', null, null, '[{"surah":2,"ayah_from":156,"ayah_to":156}]'::jsonb, null, 'published', 'verified', 'Arabic matched to the Qur''an dataset (alef-insensitive normalised comparison).', 'iqs', '{}'::text[], 70),
('grief-the-fuller-dua-for-calamity', 'The fuller dua for calamity', 'مصیبت کے وقت نعم البدل مانگنے کی دعاء', 'اللَّهُمَّ أْجُرْنِي فِي مُصِيبَتِي وَأَخْلِفْ لِي خَيْرًا مِنْهَا', 'Allāhumma''jurnī fī muṣībatī wa akhlif lī khayran minhā', 'అల్లాహుమ్మఅజుర్నీ ఫీ ముసీబతీ వ అఖ్లిఫ్ లీ ఖైరన్ మిన్హా', null, 'O Allah, reward me for my affliction and compensate me with something better than it.', null, null, null, 'hadith', 'Sahih Muslim', 'Muslim', '2126', null, '[]'::jsonb, null, 'published', 'unchecked', 'Hadith number Sahih Muslim 2126 from the Wa Iyyaka inventory (WYN-0106), reference verified against the hadith corpus in that research; numbering follows that source.', 'iqs', array['WYN-0106']::text[], 71),
('grief-for-a-deceased-loved-one', 'For a deceased loved one', 'نماز جنازہ کی دعائیں', 'اللَّهُمَّ اغْفِرْ لَهُ وَارْحَمْهُ وَعَافِهِ وَاعْفُ عَنْهُ', 'Allāhumma-ghfir lahu wa-rḥamhu wa ''āfihi wa''fu ''anh', 'అల్లాహుమ్మఘ్ఫిర్ లహు వర్హమ్హు వ ఆఫిహి వఅఫు అన్హ్', null, 'O Allah, forgive him, have mercy on him, keep him safe and sound, and pardon him.', null, null, null, 'hadith', 'Sahih Muslim', 'Muslim', null, null, '[]'::jsonb, null, 'published', 'needs_review', 'Wa Iyyaka entry WYN-0111 appears to be longer than this text (Same hadith (Muslim) but the WYN opening continues "...wa akrim nuzulahu"; IQS ends at "wa''fu anhu". IQS Arabic appears shorter than the printed WYN text. Confirm against the full text.).', 'iqs', array['WYN-0111']::text[], 72),
('grief-in-the-funeral-prayer-more-generally', 'In the funeral prayer, more generally', 'نماز جنازہ کی دعائیں', 'اللَّهُمَّ اغْفِرْ لِحَيِّنَا وَمَيِّتِنَا، وَشَاهِدِنَا وَغَائِبِنَا، وَصَغِيرِنَا وَكَبِيرِنَا', 'Allāhumma-ghfir li-ḥayyinā wa mayyitinā, wa shāhidinā wa ghā''ibinā, wa ṣaghīrinā wa kabīrinā', 'అల్లాహుమ్మఘ్ఫిర్ లిహైయినా వ మైయితినా, వ షాహిదినా వ ఘాఇబినా, వ సఘీరినా వ కబీరినా', null, 'O Allah, forgive our living and our dead, those present among us and those absent, our young and our old.', null, null, null, 'hadith', 'Sunan Abi Dawud, Jami'' at-Tirmidhi, Sunan Ibn Majah', 'Abu Dawud, Tirmidhi, Ibn Majah', '3201', 'Sahih (grade as printed in Wa Iyyaka Nasta''in)', '[]'::jsonb, null, 'published', 'unchecked', 'Hadith number Sunan Abu Dawud 3201 from the Wa Iyyaka inventory (WYN-0110), reference verified against the hadith corpus in that research; numbering follows that source.', 'iqs', array['WYN-0110']::text[], 73),
('grief-for-patience-and-steadfastness', 'For patience and steadfastness', null, 'رَبَّنَا لَا تُزِغْ قُلُوبَنَا بَعْدَ إِذْ هَدَيْتَنَا وَهَبْ لَنَا مِنْ لَدُنْكَ رَحْمَةً', 'Rabbanā lā tuzigh qulūbanā ba''da idh hadaytanā wa hab lanā min ladunka raḥmah', 'రబ్బనా లా తుజిఘ్ ఖులూబనా బఅద ఇద్ హదైతనా వ హబ్ లనా మిన్ లదున్క రహ్మహ్', null, 'Our Lord, do not let our hearts deviate after You have guided us, and grant us mercy from Yourself.', null, null, null, 'quran', null, 'Qur''an 3:8', null, null, '[{"surah":3,"ayah_from":8,"ayah_to":8}]'::jsonb, null, 'published', 'verified', 'Arabic matched to the Qur''an dataset (alef-insensitive normalised comparison).', 'iqs', '{}'::text[], 74),
('grief-upon-closing-the-eyes-of-one-who-has-died', 'Upon closing the eyes of one who has died', 'میت کی آنکھیں بند کرتے وقت کی دعاء', 'اللَّهُمَّ اغْفِرْ لِـ[فُلَانٍ] وَارْفَعْ دَرَجَتَهُ فِي الْمَهْدِيِّينَ، وَاخْلُفْهُ فِي عَقِبِهِ فِي الْغَابِرِينَ، وَاغْفِرْ لَنَا وَلَهُ يَا رَبَّ الْعَالَمِينَ، وَافْسَحْ لَهُ فِي قَبْرِهِ وَنَوِّرْ لَهُ فِيهِ', 'Allāhumma-ghfir li-[name] wa-rfa'' darajatahu fil-mahdiyyīn, wa-khlufhu fī ''aqibihi fil-ghābirīn, wa-ghfir lanā wa lahu yā Rabba-l-''ālamīn, wa-fsaḥ lahu fī qabrihi wa nawwir lahu fīh', 'అల్లాహుమ్మఘ్ఫిర్ li-[name] వర్ఫఅ దరజతహు ఫిల్మహ్దియ్యీన్, వఖ్లుఫ్హు ఫీ అఖిబిహి ఫిల్ఘాబిరీన్, వఘ్ఫిర్ లనా వ లహు యా రబ్బల్ఆలమీన్, వఫ్సహ్ లహు ఫీ ఖబ్రిహి వ నౌవిర్ లహు ఫీహ్', null, 'O Allah, forgive [name], raise his rank among those who are guided, take care of those he leaves behind, forgive us and him, O Lord of the worlds, and grant him ease and light in his grave.', null, null, null, 'hadith', 'Sahih Muslim', 'Muslim', '2130', null, '[]'::jsonb, null, 'published', 'unchecked', 'Hisnul Muslim chapter 54 (from legacy title). Hadith number Sahih Muslim 2130 from the Wa Iyyaka inventory (WYN-0109), reference verified against the hadith corpus in that research; numbering follows that source.', 'iqs', array['WYN-0109']::text[], 75),
('grief-placing-the-deceased-into-the-grave', 'Placing the deceased into the grave', 'میت کو قبر میں اتارتے وقت پڑھنے کی دعاء', 'بِسْمِ اللَّهِ وَعَلَى مِلَّةِ رَسُولِ اللَّهِ', 'Bismillāhi wa ''alā millati Rasūlillāh', 'బిస్మిల్లాహి వ అలా మిల్లతి రసూలిల్లాహ్', null, 'In the name of Allah, and according to the way of the Messenger of Allah.', null, null, null, 'hadith', 'Sunan Abi Dawud, Jami'' at-Tirmidhi', 'Abu Dawud, Tirmidhi', null, null, '[]'::jsonb, null, 'published', 'unchecked', 'Hisnul Muslim chapter 58 (from legacy title).', 'iqs', '{}'::text[], 76),
('knowledge-for-increase-in-knowledge', 'For increase in knowledge', null, 'رَبِّ زِدْنِي عِلْمًا', 'Rabbi zidnī ''ilmā', 'రబ్బి జిద్నీ ఇల్మా', null, 'My Lord, increase me in knowledge.', null, null, null, 'quran', null, 'Qur''an 20:114', null, null, '[{"surah":20,"ayah_from":114,"ayah_to":114}]'::jsonb, null, 'published', 'verified', 'Arabic matched to the Qur''an dataset (alef-insensitive normalised comparison).', 'iqs', '{}'::text[], 77),
('knowledge-before-studying-or-seeking-benefit', 'Before studying or seeking benefit', null, 'اللَّهُمَّ انْفَعْنِي بِمَا عَلَّمْتَنِي، وَعَلِّمْنِي مَا يَنْفَعُنِي', 'Allāhumma-nfa''nī bimā ''allamtanī, wa ''allimnī mā yanfa''unī', 'అల్లాహుమ్మన్ఫఅనీ బిమా అల్లమ్తనీ, వ అల్లిమ్నీ మా యన్ఫఉనీ', null, 'O Allah, benefit me with what You have taught me, and teach me what will benefit me.', null, null, null, 'hadith', 'Jami'' at-Tirmidhi, Sunan Ibn Majah', 'Tirmidhi, Ibn Majah', null, null, '[]'::jsonb, null, 'published', 'unchecked', null, 'iqs', '{}'::text[], 78),
('knowledge-istikharah-seeking-guidance-in-a-decision', 'Istikharah — seeking guidance in a decision', 'نماز استخارہ کی دعاء', 'اللَّهُمَّ إِنِّي أَسْتَخِيرُكَ بِعِلْمِكَ وَأَسْتَقْدِرُكَ بِقُدْرَتِكَ، وَأَسْأَلُكَ مِنْ فَضْلِكَ الْعَظِيمِ، فَإِنَّكَ تَقْدِرُ وَلَا أَقْدِرُ وَتَعْلَمُ وَلَا أَعْلَمُ وَأَنْتَ عَلَّامُ الْغُيُوبِ، اللَّهُمَّ إِنْ كُنْتَ تَعْلَمُ أَنَّ هَذَا الأَمْرَ خَيْرٌ لِي فِي دِينِي وَمَعَاشِي وَعَاقِبَةِ أَمْرِي (أَوْ قَالَ عَاجِلِ أَمْرِي وَآجِلِهِ) فَاقْدُرْهُ لِي وَيَسِّرْهُ لِي ثُمَّ بَارِكْ لِي فِيهِ، وَإِنْ كُنْتَ تَعْلَمُ أَنَّ هَذَا الأَمْرَ شَرٌّ لِي فِي دِينِي وَمَعَاشِي وَعَاقِبَةِ أَمْرِي (أَوْ قَالَ فِي عَاجِلِ أَمْرِي وَآجِلِهِ) فَاصْرِفْهُ عَنِّي وَاصْرِفْنِي عَنْهُ، وَاقْدُرْ لِي الْخَيْرَ حَيْثُ كَانَ ثُمَّ أَرْضِنِي بِهِ', 'Allāhumma innī astakhīruka bi-''ilmik, wa astaqdiruka bi-qudratik, wa as''aluka min faḍlika-l-''aẓīm, fa innaka taqdiru wa lā aqdir, wa ta''lamu wa lā a''lam, wa anta ''allāmu-l-ghuyūb. Allāhumma in kunta ta''lamu anna hādha-l-amra khayrun lī fī dīnī wa ma''āshī wa ''āqibati amrī (aw qāla: ''ājili amrī wa ājilih) faqdurhu lī wa yassirhu lī thumma bārik lī fīh, wa in kunta ta''lamu anna hādha-l-amra sharrun lī fī dīnī wa ma''āshī wa ''āqibati amrī (aw qāla: fī ''ājili amrī wa ājilih) faṣrifhu ''annī waṣrifnī ''anh, waqdur liya-l-khayra ḥaythu kāna thumma arḍinī bih', null, null, 'O Allah, I seek Your guidance by Your knowledge, and I seek ability from You by Your power, and I ask You from Your immense favor. You have power and I do not, You know and I do not, and You are the Knower of all unseen things. O Allah, if You know that this matter is good for me in my religion, my livelihood and the outcome of my affairs (or: in my present and future affairs), then decree it for me, make it easy for me, and then bless me in it. And if You know that this matter is bad for me in my religion, my livelihood and the outcome of my affairs (or: in my present and future affairs), then turn it away from me and turn me away from it, and decree for me the good wherever it may be, and then make me pleased with it.', null, 'Pray two non-obligatory rak''ahs, then recite this dua, naming the matter where it says "this matter".', null, 'hadith', 'Sahih al-Bukhari', 'Bukhari', '1166', null, '[]'::jsonb, null, 'published', 'needs_review', 'Arabic completed from Sahih al-Bukhari 1166 (fawazahmed0 ara-bukhari corpus; wording preserved, orthography normalised, narrator "or he said" in parentheses). The hadith number comes from the corpus numbering and the research inventory (IK1: printed Bukhari 1116 is a different hadith; the Istikhara hadith is 1166). English continuation and Latin transliteration continuation were drafted by IqraSpace — NEEDS MANUAL VERIFICATION against a scholarly translation. Telugu transliteration removed (legacy covered only the first third) — app falls back to Latin. Wa Iyyaka entry WYN-0178 appears to be longer than this text (Istikhara: IQS Arabic stops after "wa anta allamul ghuyub" and omits the continuation naming the matter (verified data error). Printed B 1116 flagged in the inventory as probable transposition of 1166. | Inventory: REFERENCE CHECK: Printed B 1116 (sunnah.com confirmed) is a hadith on praying while sitting (Imran bin Husain). The Istikhara hadith of Jabir is Sahih al-Bukhari 1166 (also 6382, 7390; T 480, N 3253, IM 1383). Likely typographical transposition; requires verification.).', 'iqs', array['WYN-0178']::text[], 79),
('repentance-general-seeking-of-forgiveness', 'General seeking of forgiveness', 'توبہ و استغفار', 'أَسْتَغْفِرُ اللَّهَ الْعَظِيمَ الَّذِي لَا إِلَهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ وَأَتُوبُ إِلَيْهِ', 'Astaghfirullāha-l-''aẓīma-lladhī lā ilāha illā huwa-l-ḥayyu-l-qayyūmu wa atūbu ilayh', 'అస్తఘ్ఫిరుల్లాహల్అజీమల్లదీ లా ఇలాహ ఇల్లా హువల్హైయుల్ఖైయూము వ అతూబు ఇలైహ్', null, 'I seek the forgiveness of Allah, the Magnificent, besides whom there is no god, the Ever-Living, the Sustainer, and I turn to Him in repentance.', null, null, null, 'hadith', 'Sunan Abi Dawud, Jami'' at-Tirmidhi', 'Abu Dawud, Tirmidhi', '3577', 'Sahih (grade as printed in Wa Iyyaka Nasta''in)', '[]'::jsonb, null, 'published', 'unchecked', 'Hadith number Jami'' at-Tirmidhi 3577 from the Wa Iyyaka inventory (WYN-0127), reference verified against the hadith corpus in that research; numbering follows that source.', 'iqs', array['WYN-0125', 'WYN-0127']::text[], 80),
('repentance-adam-and-hawwas-repentance', 'Adam and Hawwa''s repentance', 'توبہ و استغفار', 'رَبَّنَا ظَلَمْنَا أَنْفُسَنَا وَإِنْ لَمْ تَغْفِرْ لَنَا وَتَرْحَمْنَا لَنَكُونَنَّ مِنَ الْخَاسِرِينَ', 'Rabbanā ẓalamnā anfusanā wa in lam taghfir lanā wa tarḥamnā lanakūnanna mina-l-khāsirīn', 'రబ్బనా జలమ్నా అన్ఫుసనా వ ఇన్ లమ్ తఘ్ఫిర్ లనా వ తర్హమ్నా లనకూనన్న మినల్ఖాసిరీన్', null, 'Our Lord, we have wronged ourselves, and if You do not forgive us and have mercy on us, we will surely be among the losers.', null, null, null, 'quran', null, 'Qur''an 7:23', null, null, '[{"surah":7,"ayah_from":23,"ayah_to":23}]'::jsonb, null, 'published', 'verified', 'Urdu title match confidence: probable. Arabic matched to the Qur''an dataset (alef-insensitive normalised comparison).', 'iqs', array['WYN-0120']::text[], 81),
('hajj-the-talbiyah', 'The Talbiyah', 'حج یا عمرہ کا احرام باندھنے والا لبیک کیسے کہے', 'لَبَّيْكَ اللَّهُمَّ لَبَّيْكَ، لَبَّيْكَ لَا شَرِيكَ لَكَ لَبَّيْكَ، إِنَّ الْحَمْدَ وَالنِّعْمَةَ لَكَ وَالْمُلْكَ، لَا شَرِيكَ لَكَ', 'Labbayka-llāhumma labbayk, labbayka lā sharīka laka labbayk, inna-l-ḥamda wan-ni''mata laka wal-mulk, lā sharīka lak', 'లబ్బైకల్లాహుమ్మ లబ్బైక్, లబ్బైక లా షరీక లక లబ్బైక్, ఇన్నల్హమ్ద వన్నిఅమత లక వల్ముల్క్, లా షరీక లక్', null, 'Here I am, O Allah, here I am. Here I am, You have no partner, here I am. Indeed all praise, blessing, and dominion are Yours; You have no partner.', null, null, null, 'hadith', 'Sahih al-Bukhari, Sahih Muslim', 'Bukhari, Muslim', null, null, '[]'::jsonb, null, 'published', 'unchecked', null, 'iqs', '{}'::text[], 82),
('hajj-between-the-black-stone-and-yemeni-corner', 'Between the Black Stone and Yemeni Corner', 'حجر اسود اور رکن یمانی کے درمیان کی دعاء', 'رَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الْآخِرَةِ حَسَنَةً وَقِنَا عَذَابَ النَّارِ', 'Rabbanā ātinā fid-dunyā ḥasanatan wa fil-ākhirati ḥasanatan wa qinā ''adhāban-nār', 'రబ్బనా ఆతినా ఫిద్దున్యా హసనతన్ వ ఫిలాఖిరతి హసనతన్ వ ఖినా అదాబన్నార్', null, 'Our Lord, give us good in this world and good in the hereafter, and protect us from the punishment of the Fire.', null, null, null, 'mixed', 'Sunan Abi Dawud', 'Qur''an 2:201, Abu Dawud', null, null, '[{"surah":2,"ayah_from":201,"ayah_to":201}]'::jsonb, null, 'published', 'unchecked', null, 'iqs', '{}'::text[], 83),
('hajj-atop-safa-and-marwa', 'Atop Safa and Marwa', 'صفا اور مروہ کے مقام پر پڑھی جانے والی دعاء', 'لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ', 'Lā ilāha illallāhu waḥdahu lā sharīka lah, lahu-l-mulku wa lahu-l-ḥamd, wa huwa ''alā kulli shay''in qadīr', 'లా ఇలాహ ఇల్లల్లాహు వహ్దహు లా షరీక లహ్, లహుల్ముల్కు వ లహుల్హమ్ద్, వ హువ అలా కుల్లి షైఇన్ ఖదీర్', null, 'There is no god but Allah alone, without partner. His is the dominion and His is the praise, and He is over all things capable.', null, null, null, 'hadith', 'Sahih Muslim', 'Muslim', null, null, '[]'::jsonb, null, 'published', 'unchecked', null, 'iqs', '{}'::text[], 84),
('hajj-the-best-dua-on-the-day-of-arafah', 'The best dua, on the Day of Arafah', 'یوم عرفہ 9 ذو الحجہ کی دعاء', 'لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ', 'Lā ilāha illallāhu waḥdahu lā sharīka lah, lahu-l-mulku wa lahu-l-ḥamd, wa huwa ''alā kulli shay''in qadīr', 'లా ఇలాహ ఇల్లల్లాహు వహ్దహు లా షరీక లహ్, లహుల్ముల్కు వ లహుల్హమ్ద్, వ హువ అలా కుల్లి షైఇన్ ఖదీర్', null, 'There is no god but Allah alone, without partner. His is the dominion and His is the praise, and He is over all things capable — the best of all supplications is that of the Day of Arafah.', null, null, null, 'hadith', 'Jami'' at-Tirmidhi', 'Tirmidhi', null, null, '[]'::jsonb, null, 'published', 'unchecked', null, 'iqs', '{}'::text[], 85),
('social-greeting-a-fellow-muslim', 'Greeting a fellow Muslim', 'سلام عام کرنے کی فضیلت', 'السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ', 'As-salāmu ''alaykum wa raḥmatullāhi wa barakātuh', 'అస్సలాము అలైకుమ్ వ రహ్మతుల్లాహి వ బరకాతుహ్', null, 'Peace be upon you, and the mercy of Allah, and His blessings.', null, null, null, 'other', null, 'Sunnah greeting', null, null, '[]'::jsonb, null, 'published', 'needs_review', 'Reference "Sunnah greeting" is descriptive, with no collection or hadith number — find the source.', 'iqs', '{}'::text[], 86),
('social-responding-to-someone-who-sneezes-and-praises-allah', 'Responding to someone who sneezes and praises Allah', 'چھینکنے والے اور اس کا جواب دینے والے کی دعاء', 'يَرْحَمُكَ اللَّهُ', 'Yarḥamuka-llāh', 'యర్హముకల్లాహ్', null, 'May Allah have mercy on you — and the sneezer replies: Yahdīkumu-llāhu wa yuṣliḥu bālakum, ''May Allah guide you and set your affairs right.''', null, null, null, 'hadith', 'Sahih al-Bukhari', 'Bukhari', null, null, '[]'::jsonb, null, 'published', 'unchecked', null, 'iqs', '{}'::text[], 87),
('social-expiation-at-the-end-of-a-gathering', 'Expiation at the end of a gathering', 'مجلس کے کفارہ کی دعاء', 'سُبْحَانَكَ اللَّهُمَّ وَبِحَمْدِكَ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا أَنْتَ، أَسْتَغْفِرُكَ وَأَتُوبُ إِلَيْكَ', 'Subḥānaka-llāhumma wa bi-ḥamdik, ash-hadu an lā ilāha illā ant, astaghfiruka wa atūbu ilayk', 'సుబ్హానకల్లాహుమ్మ వ బిహమ్దిక్, అష్హదు అన్ లా ఇలాహ ఇల్లా అన్త్, అస్తఘ్ఫిరుక వ అతూబు ఇలైక్', null, 'Glory be to You, O Allah, and praise. I bear witness there is no god but You; I seek Your forgiveness and turn to You in repentance.', null, null, null, 'hadith', 'Jami'' at-Tirmidhi, al-Mustadrak (al-Hakim)', 'Tirmidhi, al-Hakim', null, null, '[]'::jsonb, null, 'published', 'unchecked', null, 'iqs', array['WYN-0141']::text[], 88),
('social-congratulating-a-newly-married-couple', 'Congratulating a newly married couple', 'دلہا و دلہن کو مبارکباد دینے کی دعاء', 'بَارَكَ اللَّهُ لَكَ، وَبَارَكَ عَلَيْكَ، وَجَمَعَ بَيْنَكُمَا فِي خَيْرٍ', 'Bārakallāhu lak, wa bāraka ''alayk, wa jama''a baynakumā fī khayr', 'బారకల్లాహు లక్, వ బారక అలైక్, వ జమఅ బైనకుమా ఫీ ఖైర్', null, 'May Allah bless you, shower blessings upon you, and join you both in goodness.', null, null, null, 'hadith', 'Sunan Abi Dawud, Jami'' at-Tirmidhi, Sunan Ibn Majah', 'Abu Dawud, Tirmidhi, Ibn Majah', null, null, '[]'::jsonb, null, 'published', 'unchecked', null, 'iqs', '{}'::text[], 89),
('social-upon-sneezing-said-by-the-sneezer-himself', 'Upon sneezing, said by the sneezer himself', 'چھینکنے والے اور اس کا جواب دینے والے کی دعاء', 'الْحَمْدُ لِلَّهِ', 'Al-ḥamdu lillāh', 'అల్హమ్దు లిల్లాహ్', null, 'All praise is for Allah.', null, null, null, 'hadith', 'Sahih al-Bukhari', 'Bukhari', null, null, '[]'::jsonb, null, 'published', 'unchecked', 'Hisnul Muslim chapter 77 (from legacy title).', 'iqs', '{}'::text[], 90),
('social-replying-to-may-allah-forgive-you-and-us', 'Replying to ''may Allah forgive you and us''', 'مغفرت کی دعاء دینے والے کو کیا دعاء دی جائے', 'غَفَرَ اللَّهُ لَنَا وَلَكُمْ', 'Ghafarallāhu lanā wa lakum', 'ఘఫరల్లాహు లనా వ లకుమ్', null, 'May Allah forgive us and you.', null, null, null, 'other', null, 'General Sunnah reply', null, null, '[]'::jsonb, null, 'published', 'needs_review', 'Hisnul Muslim chapter 86 (from legacy title). Reference "General Sunnah reply" is descriptive, with no collection or hadith number — find the source.', 'iqs', '{}'::text[], 91),
('social-for-someone-who-has-done-you-a-favor', 'For someone who has done you a favor', 'حسن سلوک کرنے والے کے لئے دعاء', 'جَزَاكَ اللَّهُ خَيْرًا', 'Jazākallāhu khayrā', 'జజాకల్లాహు ఖైరా', null, 'May Allah reward you with good.', null, null, null, 'hadith', 'Jami'' at-Tirmidhi', 'Tirmidhi', null, null, '[]'::jsonb, null, 'published', 'unchecked', 'Hisnul Muslim chapter 87 (from legacy title).', 'iqs', '{}'::text[], 92),
('social-reply-when-told-i-love-you-for-allahs-sake', 'Reply when told ''I love you for Allah''s sake''', 'محبت کا اظہار کرنے والے کے حق میں دعاء', 'أَحَبَّكَ الَّذِي أَحْبَبْتَنِي لَهُ', 'Aḥabbaka-lladhī aḥbabtanī lah', 'అహబ్బకల్లదీ అహ్బబ్తనీ లహ్', null, 'May He for whose sake you loved me, love you too.', null, null, null, 'hadith', 'Sunan Abi Dawud', 'Abu Dawud', null, null, '[]'::jsonb, null, 'published', 'unchecked', 'Hisnul Muslim chapter 89 (from legacy title).', 'iqs', '{}'::text[], 93),
('social-to-dispel-a-superstitious-omen', 'To dispel a superstitious omen', 'بدشگونی سے اظہار براءت کے لئے دعاء', 'اللَّهُمَّ لَا خَيْرَ إِلَّا خَيْرُكَ، وَلَا طَيْرَ إِلَّا طَيْرُكَ، وَلَا إِلَهَ غَيْرُكَ', 'Allāhumma lā khayra illā khayruk, wa lā ṭayra illā ṭayruk, wa lā ilāha ghayruk', 'అల్లాహుమ్మ లా ఖైర ఇల్లా ఖైరుక్, వ లా టైర ఇల్లా టైరుక్, వ లా ఇలాహ ఘైరుక్', null, 'O Allah, there is no good but Your good, no omen but what You ordain, and no god but You.', null, null, null, 'hadith', 'Musnad Ahmad', 'Ahmad', null, null, '[]'::jsonb, null, 'published', 'unchecked', 'Hisnul Muslim chapter 94 (from legacy title).', 'iqs', '{}'::text[], 94),
('quranic-seeking-forgiveness-for-shortcomings', 'Seeking forgiveness for shortcomings', null, 'رَبَّنَا اغْفِرْ لَنَا ذُنُوبَنَا وَإِسْرَافَنَا فِي أَمْرِنَا', 'Rabbana-ghfir lanā dhunūbanā wa isrāfanā fī amrinā', 'రబ్బనఘ్ఫిర్ లనా దునూబనా వ ఇస్రాఫనా ఫీ అమ్రినా', null, 'Our Lord, forgive us our sins and our excess in our affairs.', null, null, null, 'quran', null, 'Qur''an 3:147', null, null, '[{"surah":3,"ayah_from":147,"ayah_to":147}]'::jsonb, null, 'published', 'verified', 'Arabic matched to the Qur''an dataset (alef-insensitive normalised comparison).', 'iqs', array['WYN-0121']::text[], 95),
('quranic-for-mistakes-and-forgetfulness', 'For mistakes and forgetfulness', null, 'رَبَّنَا لَا تُؤَاخِذْنَا إِنْ نَسِينَا أَوْ أَخْطَأْنَا', 'Rabbanā lā tu''ākhidhnā in nasīnā aw akhṭa''nā', 'రబ్బనా లా తుఆఖిద్నా ఇన్ నసీనా ఔ అఖ్టఅనా', null, 'Our Lord, do not hold us accountable if we forget or make a mistake.', null, null, null, 'quran', null, 'Qur''an 2:286', null, null, '[{"surah":2,"ayah_from":286,"ayah_to":286}]'::jsonb, null, 'published', 'verified', 'Arabic matched to the Qur''an dataset (alef-insensitive normalised comparison).', 'iqs', '{}'::text[], 96),
('quranic-for-ease-and-openness-of-heart', 'For ease and openness of heart', null, 'رَبِّ اشْرَحْ لِي صَدْرِي وَيَسِّرْ لِي أَمْرِي', 'Rabbi-shraḥ lī ṣadrī wa yassir lī amrī', 'రబ్బిష్రహ్ లీ సద్రీ వ యస్సిర్ లీ అమ్రీ', null, 'My Lord, expand for me my chest, and ease for me my task.', null, null, null, 'quran', null, 'Qur''an 20:25-26', null, null, '[{"surah":20,"ayah_from":25,"ayah_to":26}]'::jsonb, null, 'published', 'verified', 'Arabic matched to the Qur''an dataset (alef-insensitive normalised comparison).', 'iqs', '{}'::text[], 97),
('quranic-for-gratitude', 'For gratitude', null, 'رَبِّ أَوْزِعْنِي أَنْ أَشْكُرَ نِعْمَتَكَ الَّتِي أَنْعَمْتَ عَلَيَّ', 'Rabbi awzi''nī an ashkura ni''mataka-llatī an''amta ''alayy', 'రబ్బి ఔజిఅనీ అన్ అష్కుర నిఅమతకల్లతీ అన్అమ్త అలైయ్', null, 'My Lord, enable me to be grateful for Your favor which You have bestowed upon me.', null, null, null, 'quran', null, 'Qur''an 27:19', null, null, '[{"surah":27,"ayah_from":19,"ayah_to":19}]'::jsonb, null, 'published', 'verified', 'Arabic matched to the Qur''an dataset (alef-insensitive normalised comparison).', 'iqs', '{}'::text[], 98),
('market-entering-the-marketplace', 'Entering the marketplace', 'بازار میں داخل ہوتے وقت پڑھنے کی دعاء', 'لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ، يُحْيِي وَيُمِيتُ، وَهُوَ حَيٌّ لَا يَمُوتُ، بِيَدِهِ الْخَيْرُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ', 'Lā ilāha illallāhu waḥdahu lā sharīka lah, lahu-l-mulku wa lahu-l-ḥamd, yuḥyī wa yumīt, wa huwa ḥayyun lā yamūt, bi-yadihi-l-khayr, wa huwa ''alā kulli shay''in qadīr', 'లా ఇలాహ ఇల్లల్లాహు వహ్దహు లా షరీక లహ్, లహుల్ముల్కు వ లహుల్హమ్ద్, యుహ్యీ వ యుమీత్, వ హువ హైయున్ లా యమూత్, బియదిహిల్ఖైర్, వ హువ అలా కుల్లి షైఇన్ ఖదీర్', null, 'There is no god but Allah alone, without partner. His is the dominion and His is the praise; He gives life and causes death, and He is Living and does not die. In His hand is all good, and He is over all things capable.', null, null, null, 'hadith', 'Jami'' at-Tirmidhi, Sunan Ibn Majah, al-Mustadrak (al-Hakim)', 'Tirmidhi, Ibn Majah, al-Hakim', null, null, '[]'::jsonb, null, 'published', 'unchecked', null, 'iqs', '{}'::text[], 99),
('market-for-beneficial-provision-after-fajr', 'For beneficial provision, after Fajr', 'سلام پھیرنے کے بعد پڑھے جانے والے اذکار', 'اللَّهُمَّ إِنِّي أَسْأَلُكَ عِلْمًا نَافِعًا، وَرِزْقًا طَيِّبًا، وَعَمَلًا مُتَقَبَّلًا', 'Allāhumma innī as''aluka ''ilman nāfi''ā, wa rizqan ṭayyibā, wa ''amalan mutaqabbalā', 'అల్లాహుమ్మ ఇన్నీ అస్అలుక ఇల్మన్ నాఫిఆ, వ రిజ్ఖన్ టైయిబా, వ అమలన్ ముతఖబ్బలా', null, 'O Allah, I ask You for beneficial knowledge, wholesome provision, and deeds that are accepted.', null, null, null, 'hadith', 'Sunan Ibn Majah', 'Ibn Majah', null, null, '[]'::jsonb, null, 'published', 'unchecked', 'Urdu title match confidence: probable.', 'iqs', array['WYN-0176']::text[], 100),
('faith-when-troubled-by-doubts-about-faith', 'When troubled by doubts about faith', 'جس شخص کو اپنے ایمان میں شک پیدا ہوجائے تو کیا کرے', 'آمَنْتُ بِاللَّهِ وَرُسُلِهِ', 'Āmantu billāhi wa rusulih', 'ఆమన్తు బిల్లాహి వ రుసులిహ్', null, 'I believe in Allah and His messengers.', null, null, null, 'hadith', 'Sahih al-Bukhari, Sahih Muslim', 'Bukhari, Muslim', null, null, '[]'::jsonb, null, 'published', 'unchecked', 'Hisnul Muslim chapter 40 (from legacy title).', 'iqs', '{}'::text[], 101),
