('wyn-0114-repentance-from-sins-and-seeking-forgiveness-exc', 'Repentance from sins and seeking forgiveness excessively opens the doors of mercy (Qur''an verses of Nuh printed: fa qultu istaghfiru rabbakum innahu kana ghaffara...)', null, 'فَقُلْتُ ٱسْتَغْفِرُوا۟ رَبَّكُمْ إِنَّهُۥ كَانَ غَفَّارًا يُرْسِلِ ٱلسَّمَآءَ عَلَيْكُم مِّدْرَارًا وَيُمْدِدْكُم بِأَمْوَٰلٍ وَبَنِينَ وَيَجْعَل لَّكُمْ جَنَّـٰتٍ وَيَجْعَل لَّكُمْ أَنْهَـٰرًا', null, null, null, 'And said, ''Ask forgiveness of your Lord. Indeed, He is ever a Perpetual Forgiver. He will send [rain from] the sky upon you in [continuing] showers And give you increase in wealth and children and provide for you gardens and provide for you rivers.', 'میں نے کہا اپنے رب سے معافی مانگو، بے شک وہ بڑا معاف کرنے والا ہے وہ تم پر آسمان سے خوب بارشیں برسائے گا تمہیں مال اور اولاد سے نوازے گا، تمہارے لیے باغ پیدا کرے گا اور تمہارے لیے نہریں جاری کر دے گا', null, null, 'quran', null, 'Qur''an 71:10-12', null, null, '[{"surah":71,"ayah_from":10,"ayah_to":12}]'::jsonb, null, 'draft', 'needs_review', 'Wa Iyyaka Nasta''in WYN-0114 (Istighfar (Seeking Forgiveness)); VERIFIED reference check in the research inventory; printed repetition: "Excessively". Arabic/English are the referenced Qur''an passage from IqraSpace''s dataset / Saheeh International; confirm this is the full wording the dua uses and add a transliteration. Printed grade: Not applicable / not printed. translation_ur = Urdu translation of the Qur''an (Al Quran Cloud ur.maududi, Tafheem ul Quran), unmodified.', 'wyn_public_pdf', array['WYN-0114']::text[], 5054),
('wyn-0115-allahummaghfirli-dhanbi', 'Allahummaghfirli dhanbi', null, '', null, null, null, null, null, null, null, 'hadith', 'Sahih Muslim', 'Sahih Muslim 6986', '6986', null, '[]'::jsonb, null, 'draft', 'needs_review', 'Wa Iyyaka Nasta''in WYN-0115 (Istighfar (Seeking Forgiveness)); VERIFIED reference check in the research inventory. STUB: no Arabic. The source book''s text is copyrighted and was not reproduced; supply the Arabic from the cited hadith (verify against a hadith corpus), then translation and transliteration. Printed grade: not graded in book (Sahihayn).', 'wyn_public_pdf', array['WYN-0115']::text[], 5055),
('wyn-0116-rabbighfirli-khatiati-yawmad-din', 'Rabbighfirli khati''ati yawmad din', null, 'وَٱلَّذِىٓ أَطْمَعُ أَن يَغْفِرَ لِى خَطِيٓـَٔتِى يَوْمَ ٱلدِّينِ', null, null, null, 'And who I aspire that He will forgive me my sin on the Day of Recompense."', null, null, null, 'mixed', 'Sahih Muslim', 'Sahih Muslim 518', '518', null, '[{"surah":26,"ayah_from":82,"ayah_to":82}]'::jsonb, null, 'draft', 'needs_review', 'Wa Iyyaka Nasta''in WYN-0116 (Istighfar (Seeking Forgiveness)); VERIFIED reference check in the research inventory. Arabic/English are the referenced Qur''an passage from IqraSpace''s dataset / Saheeh International; confirm this is the full wording the dua uses and add a transliteration. Printed grade: not graded in book (Sahihayn).', 'wyn_public_pdf', array['WYN-0116']::text[], 5056),
('wyn-0117-rabbighfir-warham-wa-anta-khairur-rahimin', 'Rabbighfir warham wa Anta khairur rahimin', null, 'وَقُل رَّبِّ ٱغْفِرْ وَٱرْحَمْ وَأَنتَ خَيْرُ ٱلرَّٰحِمِينَ', null, null, null, 'And, [O Muhammad], say, "My Lord, forgive and have mercy, and You are the best of the merciful."', 'اے محمدؐ، کہو، "میرے رب درگزر فرما، اور رحم کر، اور تو سب رحیموں سے اچھا رحیم ہے"', null, null, 'quran', null, 'Qur''an 23:118', null, null, '[{"surah":23,"ayah_from":118,"ayah_to":118}]'::jsonb, null, 'draft', 'needs_review', 'Wa Iyyaka Nasta''in WYN-0117 (Istighfar (Seeking Forgiveness)); VERIFIED reference check in the research inventory. Arabic/English are the referenced Qur''an passage from IqraSpace''s dataset / Saheeh International; confirm this is the full wording the dua uses and add a transliteration. Printed grade: Not applicable / not printed. translation_ur = Urdu translation of the Qur''an (Al Quran Cloud ur.maududi, Tafheem ul Quran), unmodified.', 'wyn_public_pdf', array['WYN-0117']::text[], 5057),
('wyn-0118-rabbanaghfirli-wali-walidayya-wa-lil-muminina-ya', 'Rabbanaghfirli wali walidayya wa lil mu''minina yawma yaqumul hisab', null, 'رَبَّنَا ٱغْفِرْ لِى وَلِوَٰلِدَىَّ وَلِلْمُؤْمِنِينَ يَوْمَ يَقُومُ ٱلْحِسَابُ', null, null, null, 'Our Lord, forgive me and my parents and the believers the Day the account is established."', 'پروردگار، مجھے اور میرے والدین کو اور سب ایمان لانے والوں کو اُس دن معاف کر دیجیو جبکہ حساب قائم ہوگا"', null, null, 'quran', null, 'Qur''an 14:41', null, null, '[{"surah":14,"ayah_from":41,"ayah_to":41}]'::jsonb, null, 'draft', 'needs_review', 'Wa Iyyaka Nasta''in WYN-0118 (Istighfar (Seeking Forgiveness)); VERIFIED reference check in the research inventory. Arabic/English are the referenced Qur''an passage from IqraSpace''s dataset / Saheeh International; confirm this is the full wording the dua uses and add a transliteration. Printed grade: Not applicable / not printed. translation_ur = Urdu translation of the Qur''an (Al Quran Cloud ur.maududi, Tafheem ul Quran), unmodified.', 'wyn_public_pdf', array['WYN-0118']::text[], 5058),
('wyn-0119-rabbana-innana-amanna-faghfirlana-dhunubana-wa-q', 'Rabbana innana amanna faghfirlana dhunubana wa qina ''adhaban nar', null, 'ٱلَّذِينَ يَقُولُونَ رَبَّنَآ إِنَّنَآ ءَامَنَّا فَٱغْفِرْ لَنَا ذُنُوبَنَا وَقِنَا عَذَابَ ٱلنَّارِ', null, null, null, 'Those who say, "Our Lord, indeed we have believed, so forgive us our sins and protect us from the punishment of the Fire,"', 'یہ وہ لوگ ہیں، جو کہتے ہیں کہ "مالک! ہم ایمان لائے، ہماری خطاؤں سے در گزر فرما اور ہمیں آتش دوزخ سے بچا لے"', null, null, 'quran', null, 'Qur''an 3:16', null, null, '[{"surah":3,"ayah_from":16,"ayah_to":16}]'::jsonb, null, 'draft', 'needs_review', 'Wa Iyyaka Nasta''in WYN-0119 (Istighfar (Seeking Forgiveness)); VERIFIED reference check in the research inventory. Arabic/English are the referenced Qur''an passage from IqraSpace''s dataset / Saheeh International; confirm this is the full wording the dua uses and add a transliteration. Printed grade: Not applicable / not printed. translation_ur = Urdu translation of the Qur''an (Al Quran Cloud ur.maududi, Tafheem ul Quran), unmodified.', 'wyn_public_pdf', array['WYN-0119']::text[], 5059),
